606		return removeUnreferencedBlobs(candidates...)
607	}
608	
609	func removeUnreferencedBlobs(candidates ...string) ([]string, error) {
610		inUse, err := retainedBlobDigestsLocked()
611		if err != nil {
612			return nil, err
613		}
614	
615		var removed []string
616		for _, digest := range candidates {
617			if digest == "" {
618				continue
619			}
620			digest, err = canonicalBlobDigest(digest)
621			if err != nil {
622				return removed, err
623			}
624			if _, used := inUse[digest]; used {
625				continue
626			}
627	
628			blob, err := BlobsPath(digest)
629			if err != nil {
630				return removed, err
631			}
632			if err := os.Remove(blob); os.IsNotExist(err) {
633				slog.Debug("blob does not exist", "digest", digest)
634			} else if err != nil {
635				return removed, err
636			} else {
637				removed = append(removed, digest)
638			}
639		}
640	
641		return removed, nil
642	}
