723	func parseManifestData(name model.Name, path string, fi os.FileInfo, digest string, data []byte, preferences []string) (*Manifest, error) {
724		m, err := parseManifest(data)
725		if err != nil {
726			return nil, err
727		}
728		if m.MediaType == MediaTypeManifestList {
729			child, err := selectManifestWithPreferences(m.Manifests, preferences)
730			if err != nil {
731				return nil, err
732			}
733			selectedDigest := child.digest
734			child.filepath = path
735			child.fi = fi
736			child.digest = digest
737			child.selectedDigest = selectedDigest
738			child.name = name
739			return child, nil
740		}
741	
742		// A single-entry preference list means the caller asked for a specific
743		// runner. Legacy manifests predate runner metadata, so derive the
744		// effective runner from the config rather than silently serving whatever
745		// is stored when the request cannot be honored.
746		if len(preferences) == 1 {
747			runner := canonicalRunner(m.Runner)
748			if runner == "" {
749				if config, err := readConfigV2(m.Config.Digest); err == nil {
750					m.parsedConfig = &config
751					runner, _ = MetadataForConfig(config)
752				}
753			}
754			if runner != "" && runner != canonicalRunner(preferences[0]) {
755				return nil, fmt.Errorf("%w for runners: %s", ErrNoCompatibleManifest, preferences[0])
756			}
757		}
758	
759		m.Runner = canonicalRunner(m.Runner)
760		m.filepath = path
761		m.fi = fi
762		m.digest = digest
763		m.name = name
764	
765		return m, nil
766	}
