800	// ResolveManifestReference resolves a manifest-list child to its full local
801	// manifest, reading and digest-verifying the referenced blob when the child is
802	// a bare reference. ok is false when the referenced blob is not local.
803	func ResolveManifestReference(child Manifest) (*Manifest, bool, error) {
