807	func resolveLocalManifestReference(child *Manifest) (*Manifest, bool, error) {
808		if child.isReference() {
809			childDigest := child.digest
810			resolved, ok, err := parseManifestBlobIfExists(child.BlobDigest())
811			if err != nil || !ok {
812				return nil, ok, err
813			}
814			if resolved.Runner == "" {
815				resolved.Runner = child.Runner
816			}
817			if resolved.Format == "" {
818				resolved.Format = child.Format
819			}
820			if resolved.digest == "" {
821				resolved.digest = childDigest
822			}
823			child = resolved
824		}
825		child.Runner = canonicalRunner(child.Runner)
826		return child, true, nil
827	}
828	
829	func selectManifestReferenceWithPreferences(manifests []Manifest, preferences []string) (*Manifest, error) {
830		for _, runner := range preferences {
831			for i := range manifests {
832				if manifests[i].MediaType != "" && manifests[i].MediaType != MediaTypeManifest {
833					continue
834				}
835				if canonicalRunner(manifests[i].Runner) != "" && canonicalRunner(manifests[i].Runner) == canonicalRunner(runner) {
836					child := manifests[i]
837					if !child.isReference() && child.digest == "" {
838						canonical, err := json.Marshal(child)
839						if err != nil {
840							return nil, err
841						}
842						sum := sha256.Sum256(canonical)
843						child.digest = fmt.Sprintf("%x", sum)
844					}
845					child.Runner = canonicalRunner(child.Runner)
846					return &child, nil
847				}
848			}
849		}
850	
851		return nil, fmt.Errorf("%w for runners: %s", ErrNoCompatibleManifest, strings.Join(preferences, ", "))
852	}
