896	// FillMetadataForConfig populates missing runner/format metadata using the
897	// model config without overwriting explicit manifest-list child metadata.
898	func FillMetadataForConfig(m *Manifest, config model.ConfigV2) {
899		runner, format := MetadataForConfig(config)
900		if m.Runner == "" {
901			m.Runner = runner
902		} else {
903			m.Runner = canonicalRunner(m.Runner)
904		}
905		if m.Format == "" {
