912	// FillMetadata populates missing runner/format metadata by reading the
913	// manifest's config blob, and canonicalizes what is already present. It
914	// returns an error when the metadata cannot be determined.
915	func FillMetadata(m *Manifest) error {
916		if m.Runner != "" && m.Format != "" {
917			m.Runner = canonicalRunner(m.Runner)
918			m.Format = strings.ToLower(strings.TrimSpace(m.Format))
919			return nil
920		}
921	
922		config, err := readConfigV2(m.Config.Digest)
923		if err != nil {
924			return err
925		}
926		FillMetadataForConfig(m, config)
927		if m.Runner == "" || m.Format == "" {
928			return errors.New("manifest is missing runner or format metadata")
929		}
930		return nil
931	}
