933	func readConfigV2(digest string) (model.ConfigV2, error) {
934		var config model.ConfigV2
935		if digest == "" {
936			return config, errors.New("manifest is missing config digest")
937		}
938	
939		configPath, err := BlobsPath(digest)
940		if err != nil {
941			return config, err
942		}
943		f, err := os.Open(configPath)
944		if err != nil {
945			return config, err
946		}
947		defer f.Close()
948	
949		return config, json.NewDecoder(f).Decode(&config)
950	}
