952	func parseManifest(data []byte) (*Manifest, error) {
953		var m Manifest
954		if err := json.Unmarshal(data, &m); err != nil {
955			return nil, err
956		}
957		if m.MediaType == MediaTypeManifestList {
958			for i := range m.Manifests {
959				if m.Manifests[i].MediaType == MediaTypeManifestList {
960					return nil, errors.New("nested manifest lists are not supported")
961				}
962				if m.Manifests[i].isReference() {
963					continue
964				}
965	
966				canonical, err := json.Marshal(m.Manifests[i])
967				if err != nil {
968					return nil, err
969				}
970				sum := sha256.Sum256(canonical)
971				m.Manifests[i].digest = fmt.Sprintf("%x", sum)
972			}
973		}
974	
975		return &m, nil
976	}
