978	func readManifestBlob(digest string) ([]byte, error) {
979		digest, err := canonicalBlobDigest(digest)
980		if err != nil {
981			return nil, err
982		}
983	
984		blobPath, err := BlobsPath(digest)
985		if err != nil {
986			return nil, err
987		}
988	
989		data, err := os.ReadFile(blobPath)
990		if err != nil {
991			return nil, err
992		}
993		if err := checkBlobDigestReader(bytes.NewReader(data), digest); err != nil {
994			return nil, err
995		}
996	
997		return data, nil
998	}
