1000	func parseManifestBlobIfExists(digest string) (*Manifest, bool, error) {
1001		data, err := readManifestBlob(digest)
1002		if err != nil {
1003			if os.IsNotExist(err) {
1004				return nil, false, nil
1005			}
1006			return nil, false, err
1007		}
1008	
1009		m, err := parseManifest(data)
1010		if err != nil {
1011			return nil, false, err
1012		}
1013	
1014		return m, true, nil
1015	}
1016	
1017	func canonicalBlobDigest(digest string) (string, error) {
1018		if _, err := BlobsPath(digest); err != nil {
1019			return "", err
1020		}
1021	
1022		return NormalizeDigest(digest), nil
1023	}
1024	
1025	// NormalizeDigest canonicalizes a blob digest for comparison: lowercase, with
1026	// the filesystem's "sha256-" separator spelling folded to "sha256:". It does
1027	// not validate the digest.
1028	func NormalizeDigest(digest string) string {
1029		return strings.ToLower(strings.Replace(strings.TrimSpace(digest), "-", ":", 1))
1030	}
1031	
1032	// SameDigest reports whether two blob digests refer to the same content,
1033	// tolerating case, separator, and bare-hex spelling differences.
1034	func SameDigest(a, b string) bool {
1035		return a != "" && blobDigest(NormalizeDigest(a)) == blobDigest(NormalizeDigest(b))
1036	}
1037	
1038	func blobDigest(digest string) string {
1039		if digest == "" {
1040			return ""
1041		}
1042	
1043		digest = strings.ToLower(digest)
1044		if strings.HasPrefix(digest, "sha256:") || strings.HasPrefix(digest, "sha256-") {
1045			return digest
1046		}
1047	
1048		return "sha256:" + digest
1049	}
