1122	func writeManifestList(name model.Name, refs []Manifest, preserveLegacy bool) (string, error) {
1123		parent := Manifest{
1124			SchemaVersion: 2,
1125			MediaType:     MediaTypeManifestList,
1126			Manifests:     refs,
1127		}
1128		data, err := json.Marshal(parent)
1129		if err != nil {
1130			return "", err
1131		}
1132		digest := fmt.Sprintf("sha256:%x", sha256.Sum256(data))
1133		if preserveLegacy {
1134			return digest, WriteManifestDataPreserveLegacy(name, data)
1135		}
1136		return digest, WriteManifestData(name, data)
1137	}
