1139	func writeManifestData(name model.Name, data []byte, removeLegacy bool) error {
1140		if !name.IsFullyQualified() {
1141			return model.Unqualified(name)
1142		}
1143	
1144		manifestStoreMu.Lock()
1145		defer manifestStoreMu.Unlock()
1146	
1147		digest, err := writeManifestBlob(data)
1148		if err != nil {
1149			return err
1150		}
1151	
1152		if err := linkManifest(name, digest); err != nil {
1153			return err
1154		}
1155	
1156		if !removeLegacy {
1157			return nil
1158		}
1159	
1160		return removeLegacyManifestPaths(name)
1161	}
