1163	// WriteLegacyAnchor writes mf as a legacy manifest at name with the v2
1164	// manifest blobs named by manifestDigests appended as layers. The extra layers
1165	// exist only so a pre-manifest-list daemon's garbage collector, which retains
1166	// just the digests listed by legacy manifests, cannot delete the manifest
1167	// blobs during a downgrade.
1168	func WriteLegacyAnchor(name model.Name, mf *Manifest, manifestDigests ...string) error {
1169		if mf == nil {
1170			return errors.New("downgrade anchor requires a manifest")
1171		}
1172	
1173		anchor := *mf
1174		anchor.Layers = slices.Clone(mf.Layers)
1175		for _, manifestDigest := range manifestDigests {
1176			digest, err := canonicalBlobDigest(manifestDigest)
1177			if err != nil {
1178				return err
1179			}
1180			data, err := readManifestBlob(digest)
1181			if err != nil {
1182				return err
1183			}
1184			mediaType := MediaTypeManifest
1185			var m Manifest
1186			if err := json.Unmarshal(data, &m); err == nil && m.MediaType == MediaTypeManifestList {
1187				mediaType = MediaTypeManifestList
1188			}
1189			anchor.Layers = append(anchor.Layers, Layer{
1190				MediaType: mediaType,
1191				Digest:    digest,
1192				Size:      int64(len(data)),
1193			})
1194		}
1195	
1196		data, err := json.Marshal(anchor)
1197		if err != nil {
1198			return err
1199		}
1200	
1201		return WriteLegacyManifestData(name, data)
1202	}
1203	
1204	// WriteLegacyManifestData stores raw manifest bytes in the legacy named
1205	// manifest tree for compatibility with older Ollama releases.
1206	func WriteLegacyManifestData(name model.Name, data []byte) error {
1207		if !name.IsFullyQualified() {
1208			return model.Unqualified(name)
1209		}
1210	
1211		manifestStoreMu.Lock()
1212		defer manifestStoreMu.Unlock()
1213	
1214		name = normalizeLogicalName(name)
1215		if !legacyManifestPathSupported(name) {
1216			return nil
1217		}
1218	
1219		manifestPath, err := LegacyPathForName(name)
1220		if err != nil {
1221			return err
1222		}
1223		if err := os.MkdirAll(filepath.Dir(manifestPath), 0o755); err != nil {
1224			return err
1225		}
1226	
1227		temp, err := os.CreateTemp(filepath.Dir(manifestPath), ".manifest-*")
1228		if err != nil {
1229			return err
1230		}
1231		tempName := temp.Name()
1232		defer os.Remove(tempName)
1233	
1234		if _, err := temp.Write(data); err != nil {
1235			temp.Close()
1236			return err
1237		}
1238		if err := temp.Close(); err != nil {
1239			return err
1240		}
1241		if err := os.Chmod(tempName, 0o644); err != nil {
1242			return err
1243		}
1244	
1245		return replaceManifestPath(tempName, manifestPath)
1246	}
