1248	func linkManifest(name model.Name, digest string) error {
1249		manifestPath, err := V2PathForName(name)
1250		if err != nil {
1251			return err
1252		}
1253		blobPath, err := BlobsPath(digest)
1254		if err != nil {
1255			return err
1256		}
1257		if _, err := os.Stat(blobPath); err != nil {
1258			return err
1259		}
1260		if err := checkBlobDigest(blobPath, digest); err != nil {
1261			return err
1262		}
1263	
1264		if err := os.MkdirAll(filepath.Dir(manifestPath), 0o755); err != nil {
1265			return err
1266		}
1267	
1268		// Avoid symlinks on windows
1269		if runtime.GOOS == "windows" {
1270			return copyManifestFile(blobPath, manifestPath)
