func TestParseManifestListByDigestReference(t *testing.T) {
	t.Setenv("OLLAMA_MODELS", t.TempDir())

	child := createManifestForTest(
		"sha256:"+strings.Repeat("a", 64),
		"sha256:"+strings.Repeat("b", 64),
		RunnerGGML,
	)
	childData, err := json.Marshal(child)
	if err != nil {
		t.Fatal(err)
	}
	childDigest := writeManifestBlobForTest(t, childData)
	childRef, err := NewManifestReference(childDigest, RunnerGGML, FormatGGUF)
	if err != nil {
		t.Fatal(err)
	}

	parentData := createManifestListData(t, childRef)
	parentDigest := writeManifestBlobForTest(t, parentData)
	parentRef := strings.Replace(parentDigest, ":", "-", 1)

	raw, err := ReadManifestData(model.ParseName(parentRef))
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(raw, parentData) {
		t.Fatal("ReadManifestData() returned different parent manifest bytes")
	}

	got, err := ParseNamedManifestForRunner(model.ParseName(parentRef), RunnerGGML)
	if err != nil {
		t.Fatal(err)
	}
	if got.BlobDigest() != parentDigest {
		t.Fatalf("BlobDigest() = %q, want parent %q", got.BlobDigest(), parentDigest)
	}
	if got.SelectedDigest() != strings.TrimPrefix(childDigest, "sha256:") {
		t.Fatalf("SelectedDigest() = %q, want child %q", got.SelectedDigest(), strings.TrimPrefix(childDigest, "sha256:"))
	}
	if got.Runner != RunnerGGML {
		t.Fatalf("Runner = %q, want %q", got.Runner, RunnerGGML)
	}
}

