package manifest

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"

	"github.com/ollama/ollama/types/model"
)

// quarantineDirName holds manifests that could not be trusted at audit time.
// Entries never leave automatically: repair or an explicit model delete is the
// only way out, and while quarantined every digest the manifest referenced is
// retained, so corruption can never trigger garbage collection of weights.
const quarantineDirName = "quarantine"

// QuarantineEntry describes one manifest moved aside during an audit.
type QuarantineEntry struct {
	// Model is the logical name the manifest was stored under.
	Model model.Name `json:"model"`
	// Path is the manifest path the entry was moved from, relative to the
	// models directory.
	Path string `json:"path"`
	// QuarantinedPath is where the bytes were moved to, relative to the
	// models directory.
	QuarantinedPath string `json:"quarantinedPath"`
	// Reason explains why the manifest could not be trusted.
	Reason string `json:"reason"`
	// References are the blob digests salvaged from the manifest, including
	// best-effort extractions from unparseable bytes. They are retained
	// until the entry is repaired or explicitly removed.
	References []string `json:"references"`
	// QuarantinedAt records when the entry was created.
	QuarantinedAt time.Time `json:"quarantinedAt"`
}

func quarantineDir() (string, error) {
	blobs, err := BlobsPath("")
	if err != nil {
		return "", err
	}
	return filepath.Join(filepath.Dir(blobs), quarantineDirName), nil
}

// quarantineFileName flattens a manifest path into a unique, filesystem-safe
// name: host/namespace/model/tag -> host_namespace_model_tag plus a short
// disambiguator derived from the original path.
func quarantineFileName(relPath string) string {
	name := strings.NewReplacer(string(filepath.Separator), "_", ":", "%3A", "/", "_").Replace(relPath)
	return name
}

// quarantineManifest moves an untrusted manifest file into the quarantine
// directory and records why. It is idempotent: re-quarantining an entry with
// the same origin never overwrites the first record and returns the existing
// entry. A quarantine write failure leaves the original manifest untouched and
// returns a readable reason.
func quarantineManifest(relPath, root string, reason string, references []string) (*QuarantineEntry, error) {
	dir, err := quarantineDir()
	if err != nil {
		return nil, err
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return nil, fmt.Errorf("create quarantine directory: %w", err)
	}

	base := quarantineFileName(relPath)
	blobDest := filepath.Join(dir, base)
	metaPath := filepath.Join(dir, base+".json")

	// Idempotency: an existing record with the same origin wins. Never
	// overwrite a prior quarantine entry.
	if existing, err := readQuarantineEntry(metaPath); err == nil {
		return existing, nil
	} else if !errors.Is(err, os.ErrNotExist) {
		return nil, fmt.Errorf("read quarantine record %s: %w", base, err)
	}

	src := filepath.Join(root, relPath)
	entry := &QuarantineEntry{
		Path:             filepath.ToSlash(relPath),
		QuarantinedPath:  filepath.ToSlash(filepath.Join(quarantineDirName, base)),
		Reason:           reason,
		References:       uniqueSortedDigests(references),
		QuarantinedAt:    time.Now().UTC(),
	}
	if n := parseStoredManifestFilepath(relPath); n.IsValid() {
		entry.Model = normalizeLogicalName(n)
	}

	// Move the bytes first. Rename within the same filesystem is atomic; a
	// failure here means the manifest stays where it was and nothing about
	// the store's reference set changes.
	if err := os.Rename(src, blobDest); err != nil && !os.IsNotExist(err) {
		return nil, fmt.Errorf("quarantine manifest %s: %w", relPath, err)
	}

	meta, err := json.MarshalIndent(entry, "", "  ")
	if err != nil {
		return nil, err
	}
	tmp := metaPath + ".tmp"
	if err := os.WriteFile(tmp, meta, 0o644); err != nil {
		return nil, fmt.Errorf("write quarantine record %s: %w", base, err)
	}
	if err := os.Rename(tmp, metaPath); err != nil {
		return nil, fmt.Errorf("finalize quarantine record %s: %w", base, err)
	}

	return entry, nil
}

func readQuarantineEntry(metaPath string) (*QuarantineEntry, error) {
	data, err := os.ReadFile(metaPath)
	if err != nil {
		return nil, err
	}
	var entry QuarantineEntry
	if err := json.Unmarshal(data, &entry); err != nil {
		return nil, err
	}
	return &entry, nil
}

// listQuarantineEntries returns every quarantine record, sorted by model name
// for deterministic reports. A directory that does not exist yet is empty.
func listQuarantineEntries() ([]*QuarantineEntry, error) {
	dir, err := quarantineDir()
	if err != nil {
		return nil, err
	}
	matches, err := filepath.Glob(filepath.Join(dir, "*.json"))
	if err != nil {
		return nil, err
	}

	entries := make([]*QuarantineEntry, 0, len(matches))
	for _, match := range matches {
		entry, err := readQuarantineEntry(match)
		if err != nil {
			continue
		}
		entries = append(entries, entry)
	}
	sort.Slice(entries, func(i, j int) bool {
		return entries[i].Path < entries[j].Path
	})
	return entries, nil
}

// removeQuarantineEntry deletes the record and the quarantined bytes for one
// entry. Missing files are tolerated so repeated cleanup stays idempotent.
func removeQuarantineEntry(entry *QuarantineEntry) error {
	dir, err := quarantineDir()
	if err != nil {
		return err
	}
	base := quarantineFileName(filepath.FromSlash(entry.Path))
	for _, p := range []string{
		filepath.Join(dir, base),
		filepath.Join(dir, base+".json"),
	} {
		if err := os.Remove(p); err != nil && !os.IsNotExist(err) {
			return err
		}
	}
	return nil
}

// salvageDigests extracts every plausible sha256 blob digest from raw manifest
// bytes. It is deliberately conservative and lexical: when JSON cannot be
// parsed at all, any digest-shaped string is treated as a reference so that an
// unreadable manifest can never cause its layers to be reclaimed. Duplicates
// are collapsed.
func salvageDigests(data []byte) []string {
	seen := make(map[string]struct{})
	var digests []string
	add := func(raw string) {
		digest, ok := ResolveDigestReference(strings.TrimSpace(raw))
		if !ok || digest == "" {
			return
		}
		digest = NormalizeDigest(digest)
		if ValidateDigest(digest) != nil {
			return
		}
		if _, ok := seen[digest]; ok {
			return
		}
		seen[digest] = struct{}{}
		digests = append(digests, digest)
	}

	// First try structured extraction so valid-but-otherwise-broken manifests
	// still produce an exact reference set.
	var m Manifest
	if err := json.Unmarshal(data, &m); err == nil {
		for _, layer := range append(m.Layers, m.Config) {
			add(layer.Digest)
		}
		for _, child := range m.Manifests {
			add(child.BlobDigest())
		}
	}

	// Lexical backstop: every sha256-<64 hex> or sha256:<64 hex> occurrence,
	// regardless of whether the document still parses.
	for _, match := range digestTokenPattern.FindAllString(string(data), -1) {
		add(match)
	}
	return uniqueSortedDigests(digests)
}

func uniqueSortedDigests(digests []string) []string {
	seen := make(map[string]struct{})
	out := make([]string, 0, len(digests))
	for _, d := range digests {
		if d == "" {
			continue
		}
		d = NormalizeDigest(d)
		if ValidateDigest(d) != nil {
			continue
		}
		if _, ok := seen[d]; ok {
			continue
		}
		seen[d] = struct{}{}
		out = append(out, d)
	}
	sort.Strings(out)
	return out
}
