// TakeSnapshot walks the store once and builds the single Snapshot used by
// verification, reclamation and reporting. The store mutex is held for the
// filesystem walk so a concurrent delete or manifest write cannot make the
// reference set and the blob set diverge; byte verification happens after the
// walk without holding the mutex and tolerates concurrent change.
func TakeSnapshot(opts AuditOptions) (*Snapshot, error) {
	if opts.ChunkSize <= 0 {
		opts.ChunkSize = DefaultAuditChunkSize
	}
	if opts.Now == nil {
		opts.Now = time.Now
	}
	if opts.MinTempAge <= 0 {
		opts.MinTempAge = layerPruneMinTempAge()
	}

	manifestStoreMu.Lock()
	snap, err := takeSnapshotLocked(opts)
	manifestStoreMu.Unlock()
	if err != nil {
		return nil, err
	}

	if opts.VerifyBytes {
		verifySnapshotBlobs(snap, opts)
	}

	computeReclaimEstimate(snap, opts)
	return snap, nil
}

func takeSnapshotLocked(opts AuditOptions) (*Snapshot, error) {
