// TotalSizeForName returns the combined size of unique config and layer blobs
// reachable from the named manifest object. Manifest blobs themselves are not
// included in the total.
func TotalSizeForName(n model.Name) (int64, error) {
	if !n.IsFullyQualified() {
		return 0, model.Unqualified(n)
	}

	p, root, err := resolveManifestPath(n)
	if err != nil {
		return 0, err
	}

	data, _, _, err := readVerifiedManifest(p, root)
	if err != nil {
		return 0, err
	}

	return totalSizeForManifestData(data)
}

func (m *Manifest) Digest() string {
	return m.digest
}

// Name returns the model name associated with a parsed named manifest.
func (m *Manifest) Name() model.Name {
	return m.name
}

// ParsedConfig returns config data already read while checking a legacy
// manifest's explicit runner selection, when that check was needed.
func (m *Manifest) ParsedConfig() (model.ConfigV2, bool) {
	if m.parsedConfig == nil {
		return model.ConfigV2{}, false
	}
	return *m.parsedConfig, true
}

// SelectedDigest returns the digest of the runnable manifest selected from a
// manifest list. For non-list manifests, it is the same as Digest.
func (m *Manifest) SelectedDigest() string {
	if m.selectedDigest != "" {
		return m.selectedDigest
	}

	return m.digest
}

func (m *Manifest) BlobDigest() string {
	if m.digest == "" {
		return ""
	}

	return "sha256:" + m.digest
}

func (m *Manifest) FileInfo() os.FileInfo {
	return m.fi
}

// ConfigLayer returns the JSON layer stored under configPath.
func (m *Manifest) ConfigLayer(configPath string) (Layer, bool) {
	for _, layer := range m.Layers {
		if layer.MediaType == "application/vnd.ollama.image.json" && layer.Name == configPath {
			return layer, true
		}
	}
	return Layer{}, false
}

// ReadConfig returns the contents of the JSON layer stored under configPath.
func (m *Manifest) ReadConfig(configPath string) ([]byte, error) {
	layer, ok := m.ConfigLayer(configPath)
	if !ok {
		return nil, fmt.Errorf("config %q not found in manifest", configPath)
	}
	blobPath, err := BlobsPath(layer.Digest)
	if err != nil {
		return nil, err
	}
	return os.ReadFile(blobPath)
}

// ReadConfigJSON reads and unmarshals a config layer as JSON.
func (m *Manifest) ReadConfigJSON(configPath string, v any) error {
	data, err := m.ReadConfig(configPath)
	if err != nil {
		return err
	}
	return json.Unmarshal(data, v)
}

// TensorLayers returns the layers holding tensor data.
func (m *Manifest) TensorLayers() []Layer {
	var layers []Layer
	for _, layer := range m.Layers {
		if layer.MediaType == MediaTypeImageTensor {
			layers = append(layers, layer)
		}
	}
	return layers
}

// RemoveNamed removes a named manifest object and then removes any blobs that
// were reachable only from that object. The removed blob digests are returned
// even alongside an error, so callers can clean up anything derived from
// them.
func RemoveNamed(n model.Name) ([]string, error) {
	if digest, ok, err := ResolveDigestReferenceName(n); err != nil {
		return nil, err
	} else if ok {
		return removeDigestReference(digest)
	}

	candidates, err := ReferencedBlobDigestsForName(n)
	if err != nil {
		return nil, err
	}

	if err := removeNamedManifestPaths(n); err != nil {
		return nil, err
	}

	return RemoveUnreferencedBlobs(candidates...)
}

func removeDigestReference(digest string) ([]string, error) {
	data, err := readManifestBlob(digest)
	if err != nil {
		return nil, err
	}

	digest, err = canonicalBlobDigest(digest)
	if err != nil {
		return nil, err
	}

	candidates, err := referencedBlobDigestsForData(digest, data)
	if err != nil {
		return nil, err
	}

	extraCandidates, err := removeDigestFromManifestLists(digest)
	if err != nil {
		return nil, err
	}

	if err := removeNamedManifestPathsForDigest(digest); err != nil {
		return nil, err
	}

	candidates = append(candidates, extraCandidates...)
	return RemoveUnreferencedBlobs(candidates...)
}

// ChildManifestDigest returns the digest identifying a manifest-list child:
// its blob digest when it is a reference, otherwise the digest of its
// canonical JSON encoding.
func ChildManifestDigest(child Manifest) (string, error) {
	if digest := child.BlobDigest(); digest != "" {
		return digest, nil
	}

	data, err := json.Marshal(child)
	if err != nil {
		return "", err
	}
	sum := sha256.Sum256(data)
	return fmt.Sprintf("sha256:%x", sum), nil
}

func removeDigestFromManifestLists(digest string) ([]string, error) {
	target := strings.TrimPrefix(digest, "sha256:")
	refs, err := namedManifestRefs(true)
	if err != nil {
		return nil, err
	}

	var candidates []string
	for n, ref := range refs {
		data, _, parentDigest, err := readVerifiedManifest(ref.path, ref.root)
		if err != nil {
			slog.Warn("bad manifest", "name", n, "error", err)
			continue
		}

		parent, err := parseManifest(data)
		if err != nil {
			slog.Warn("bad manifest", "name", n, "error", err)
			continue
		}
		if parent.MediaType != MediaTypeManifestList {
			continue
		}

		kept := parent.Manifests[:0]
		removed := false
		for _, child := range parent.Manifests {
			childDigest, err := ChildManifestDigest(child)
			if err != nil {
				return candidates, err
			}
			if strings.EqualFold(strings.TrimPrefix(childDigest, "sha256:"), target) {
				removed = true
				continue
			}
			kept = append(kept, child)
		}
		if !removed {
			continue
		}

		candidates = append(candidates, blobDigest(parentDigest))
		if len(kept) == 0 {
			if err := removeNamedManifestPaths(n); err != nil {
				return candidates, err
			}
			continue
		}

		parent.Manifests = kept
		updated, err := json.Marshal(parent)
		if err != nil {
			return candidates, err
		}
		if err := WriteManifestData(n, updated); err != nil {
			return candidates, err
		}
	}

	return candidates, nil
}

func removeNamedManifestPathsForDigest(digest string) error {
	digest, err := canonicalBlobDigest(digest)
	if err != nil {
		return err
	}
	target := strings.TrimPrefix(digest, "sha256:")

	refs, err := namedManifestRefs(true)
	if err != nil {
		return err
	}
	for n, ref := range refs {
		_, _, refDigest, err := readVerifiedManifest(ref.path, ref.root)
		if err != nil {
			slog.Warn("bad manifest", "name", n, "error", err)
			continue
		}
		if !strings.EqualFold(refDigest, target) {
			continue
		}
		if err := os.Remove(ref.path); err != nil && !os.IsNotExist(err) {
			return err
		}
	}

	return pruneManifestRoots()
}

// ReferencedBlobDigestsForName returns the blob digests reachable from the
// named manifest object as stored on disk. Manifest lists include the parent
// list blob, every child manifest blob, and each child's config and layer blobs.
func ReferencedBlobDigestsForName(n model.Name) ([]string, error) {
	if !n.IsFullyQualified() {
		return nil, model.Unqualified(n)
	}

	p, root, err := resolveManifestPath(n)
	if err != nil {
		return nil, err
	}

	data, _, digest, err := readVerifiedManifest(p, root)
	if err != nil {
		return nil, err
	}

	return referencedBlobDigestsForData(digest, data)
}

// retainedBlobDigestsLocked returns the complete set of blob digests reachable from
// all named manifest objects in the local store. Manifests that cannot be read
// or parsed do not silently release their blobs: the digests still embedded in
// their bytes are retained too, and anything held in quarantine is retained
// until repaired or explicitly removed.
func retainedBlobDigestsLocked() (map[string]struct{}, error) {
	refs, err := namedManifestRefs(true)
	if err != nil {
		return nil, err
	}

	retained := make(map[string]struct{})
	for n, ref := range refs {
		data, _, digest, err := readVerifiedManifestLocked(ref.path, ref.root)
		if err != nil {
			slog.Warn("bad manifest", "name", n, "error", err)
			// Retain every digest-shaped token so an unreadable manifest can
			// never orphan the layers it references.
			raw, readErr := os.ReadFile(ref.path)
			if readErr != nil {
				continue
			}
			for _, d := range salvageDigests(raw) {
				retained[d] = struct{}{}
			}
			continue
		}

		digests, err := referencedBlobDigestsForData(digest, data)
		if err != nil {
			slog.Warn("bad manifest", "name", n, "error", err)
			for _, d := range salvageDigests(data) {
				retained[d] = struct{}{}
			}
			continue
		}

		for _, digest := range digests {
			retained[digest] = struct{}{}
		}
	}

	// Quarantined manifests keep every blob they referenced until an
	// operator repairs or deletes them.
	if entries, err := listQuarantineEntries(); err != nil {
		slog.Warn("could not read quarantine entries", "error", err)
	} else {
		for _, entry := range entries {
			for _, d := range entry.References {
				if ValidateDigest(d) == nil {
					retained[NormalizeDigest(d)] = struct{}{}
				}
			}
		}
	}

	return retained, nil
}

func referencedBlobDigestsForData(manifestDigest string, data []byte) ([]string, error) {
	var digests []string
	seen := make(map[string]struct{})

	add := func(digest string) error {
		if digest == "" {
			return nil
		}

		digest, err := canonicalBlobDigest(digest)
		if err != nil {
			return err
		}
		if _, ok := seen[digest]; ok {
			return nil
		}
		seen[digest] = struct{}{}
		digests = append(digests, digest)

		return nil
	}
	addManifest := func(m *Manifest) error {
		for _, layer := range append(m.Layers, m.Config) {
			if err := add(layer.Digest); err != nil {
				return err
			}
		}

		return nil
	}

	if err := add(blobDigest(manifestDigest)); err != nil {
		return nil, err
	}

	m, err := parseManifest(data)
	if err != nil {
		return nil, err
	}
	if m.MediaType == MediaTypeManifestList {
		for i := range m.Manifests {
			child := &m.Manifests[i]
			if err := add(child.BlobDigest()); err != nil {
				return nil, err
			}
			if child.isReference() {
				resolved, ok, err := parseManifestBlobIfExists(child.BlobDigest())
				if err != nil {
					return nil, err
				}
				if !ok {
					continue
				}
				child = resolved
			}
			if err := addManifest(child); err != nil {
				return nil, err
			}
		}

		return digests, nil
	}

	if err := addManifest(m); err != nil {
		return nil, err
	}

	return digests, nil
}

func totalSizeForManifestData(data []byte) (int64, error) {
	seen := make(map[string]struct{})

	addLayer := func(layer Layer) (int64, error) {
		if layer.Digest == "" {
			return 0, nil
		}

		digest, err := canonicalBlobDigest(layer.Digest)
		if err != nil {
			return 0, err
		}
		if _, ok := seen[digest]; ok {
			return 0, nil
		}
		seen[digest] = struct{}{}

		return layer.Size, nil
	}

	addManifest := func(m *Manifest) (int64, error) {
		var size int64
		for _, layer := range append(m.Layers, m.Config) {
			layerSize, err := addLayer(layer)
			if err != nil {
				return 0, err
			}
			size += layerSize
		}

		return size, nil
	}

	m, err := parseManifest(data)
	if err != nil {
		return 0, err
	}
	if m.MediaType == MediaTypeManifestList {
		var size int64
		for i := range m.Manifests {
			child := &m.Manifests[i]
			if child.isReference() {
				resolved, ok, err := parseManifestBlobIfExists(child.BlobDigest())
				if err != nil {
					return 0, err
				}
				if !ok {
					continue
				}
				child = resolved
			}

			childSize, err := addManifest(child)
			if err != nil {
				return 0, err
			}
			size += childSize
		}

		return size, nil
	}

	return addManifest(m)
}

// RemoveUnreferencedBlobs removes the candidate blobs that no other manifest
// references. The digests it removed are returned even alongside an error, so
// callers can clean up anything derived from them.
func RemoveUnreferencedBlobs(candidates ...string) ([]string, error) {
	manifestStoreMu.Lock()
	defer manifestStoreMu.Unlock()

	return removeUnreferencedBlobs(candidates...)
}

func removeUnreferencedBlobs(candidates ...string) ([]string, error) {
	inUse, err := retainedBlobDigestsLocked()
	if err != nil {
		return nil, err
	}

	var removed []string
	for _, digest := range candidates {
		if digest == "" {
			continue
		}
		digest, err = canonicalBlobDigest(digest)
		if err != nil {
			return removed, err
		}
		if _, used := inUse[digest]; used {
			continue
		}

		blob, err := BlobsPath(digest)
		if err != nil {
			return removed, err
		}
		if err := os.Remove(blob); os.IsNotExist(err) {
			slog.Debug("blob does not exist", "digest", digest)
		} else if err != nil {
			return removed, err
		} else {
			removed = append(removed, digest)
		}
	}

	return removed, nil
}

func ParseNamedManifest(n model.Name) (*Manifest, error) {
	return parseNamedManifest(n, runnerPreferences())
}

// ParseNamedManifestForRunner returns the named manifest selected for runner.
// If the named object is a manifest list, runner must match one child entry.
func ParseNamedManifestForRunner(n model.Name, runner string) (*Manifest, error) {
	return parseNamedManifest(n, runnerPreferencesFor(runner))
}

func parseNamedManifest(n model.Name, preferences []string) (*Manifest, error) {
	if !n.IsFullyQualified() {
		return nil, model.Unqualified(n)
	}

	p, root, err := resolveManifestPath(n)
	if err != nil {
		return nil, err
	}

	return parseManifestFile(normalizeLogicalName(n), p, root, preferences)
}

func ReadManifestData(n model.Name) ([]byte, error) {
	if !n.IsFullyQualified() {
		return nil, model.Unqualified(n)
	}

	p, root, err := resolveManifestPath(n)
	if err != nil {
		return nil, err
	}

	data, _, _, err := readVerifiedManifest(p, root)
	return data, err
}

// ReadSelectedManifestData returns the runnable manifest bytes for a named
// model. If the named object is a manifest list, it returns the selected child
// manifest according to local runner preferences.
func ReadSelectedManifestData(n model.Name) ([]byte, error) {
	if !n.IsFullyQualified() {
		return nil, model.Unqualified(n)
	}

	p, root, err := resolveManifestPath(n)
	if err != nil {
		return nil, err
	}

	data, _, _, err := readVerifiedManifest(p, root)
	if err != nil {
		return nil, err
	}

	m, err := parseManifest(data)
	if err != nil {
		return nil, err
	}
	if m.MediaType == MediaTypeManifestList {
		child, err := selectManifest(m.Manifests)
		if err != nil {
			return nil, err
		}
		return json.Marshal(child)
	}

	return data, nil
}

func parseManifestFile(name model.Name, path, root string, preferences []string) (*Manifest, error) {
	data, fi, digest, err := readVerifiedManifest(path, root)
	if err != nil {
		return nil, err
	}

	return parseManifestData(name, path, fi, digest, data, preferences)
}

func parseManifestData(name model.Name, path string, fi os.FileInfo, digest string, data []byte, preferences []string) (*Manifest, error) {
	m, err := parseManifest(data)
	if err != nil {
		return nil, err
	}
	if m.MediaType == MediaTypeManifestList {
		child, err := selectManifestWithPreferences(m.Manifests, preferences)
		if err != nil {
			return nil, err
		}
		selectedDigest := child.digest
		child.filepath = path
		child.fi = fi
		child.digest = digest
		child.selectedDigest = selectedDigest
		child.name = name
		return child, nil
	}

	// A single-entry preference list means the caller asked for a specific
	// runner. Legacy manifests predate runner metadata, so derive the
	// effective runner from the config rather than silently serving whatever
	// is stored when the request cannot be honored.
	if len(preferences) == 1 {
		runner := canonicalRunner(m.Runner)
		if runner == "" {
			if config, err := readConfigV2(m.Config.Digest); err == nil {
				m.parsedConfig = &config
				runner, _ = MetadataForConfig(config)
			}
		}
		if runner != "" && runner != canonicalRunner(preferences[0]) {
			return nil, fmt.Errorf("%w for runners: %s", ErrNoCompatibleManifest, preferences[0])
		}
	}

	m.Runner = canonicalRunner(m.Runner)
	m.filepath = path
	m.fi = fi
	m.digest = digest
	m.name = name

	return m, nil
}

func selectManifest(manifests []Manifest) (*Manifest, error) {
	return selectManifestWithPreferences(manifests, runnerPreferences())
}

// SelectManifestReferenceForRunner returns the manifest-list child selected for runner
// without resolving it from the local blob store.
func SelectManifestReferenceForRunner(manifests []Manifest, runner string) (*Manifest, error) {
	return selectManifestReferenceWithPreferences(manifests, runnerPreferencesFor(runner))
}

func selectManifestWithPreferences(manifests []Manifest, preferences []string) (*Manifest, error) {
	for _, runner := range preferences {
		child, err := selectManifestReferenceWithPreferences(manifests, []string{runner})
		if err != nil {
			if errors.Is(err, ErrNoCompatibleManifest) {
				continue
			}
			return nil, err
		}

		resolved, ok, err := resolveLocalManifestReference(child)
		if err != nil {
			return nil, err
		}
		if ok {
			return resolved, nil
		}
	}

	return nil, fmt.Errorf("%w for runners: %s", ErrNoCompatibleManifest, strings.Join(preferences, ", "))
}

// ResolveManifestReference resolves a manifest-list child to its full local
// manifest, reading and digest-verifying the referenced blob when the child is
// a bare reference. ok is false when the referenced blob is not local.
func ResolveManifestReference(child Manifest) (*Manifest, bool, error) {
	return resolveLocalManifestReference(&child)
}

func resolveLocalManifestReference(child *Manifest) (*Manifest, bool, error) {
	if child.isReference() {
		childDigest := child.digest
		resolved, ok, err := parseManifestBlobIfExists(child.BlobDigest())
		if err != nil || !ok {
			return nil, ok, err
		}
		if resolved.Runner == "" {
			resolved.Runner = child.Runner
		}
		if resolved.Format == "" {
			resolved.Format = child.Format
		}
		if resolved.digest == "" {
			resolved.digest = childDigest
		}
		child = resolved
	}
	child.Runner = canonicalRunner(child.Runner)
	return child, true, nil
}

func selectManifestReferenceWithPreferences(manifests []Manifest, preferences []string) (*Manifest, error) {
	for _, runner := range preferences {
		for i := range manifests {
			if manifests[i].MediaType != "" && manifests[i].MediaType != MediaTypeManifest {
				continue
			}
			if canonicalRunner(manifests[i].Runner) != "" && canonicalRunner(manifests[i].Runner) == canonicalRunner(runner) {
				child := manifests[i]
				if !child.isReference() && child.digest == "" {
					canonical, err := json.Marshal(child)
					if err != nil {
						return nil, err
					}
					sum := sha256.Sum256(canonical)
					child.digest = fmt.Sprintf("%x", sum)
				}
				child.Runner = canonicalRunner(child.Runner)
				return &child, nil
			}
		}
	}

	return nil, fmt.Errorf("%w for runners: %s", ErrNoCompatibleManifest, strings.Join(preferences, ", "))
}

func runnerPreferences() []string {
	if runtime.GOOS == "darwin" && runtime.GOARCH == "arm64" {
		return []string{RunnerMLX, RunnerLlamaCPP, RunnerGGML}
	}

	return []string{RunnerLlamaCPP, RunnerGGML, RunnerMLX}
}

// IsTopRunnerPreference reports whether runner is the first runner the
// platform would select from a manifest list when no runner is requested.
func IsTopRunnerPreference(runner string) bool {
	return canonicalRunner(runner) == runnerPreferences()[0]
}

func runnerPreferencesFor(runner string) []string {
	runner = canonicalRunner(runner)
	if runner == "" {
		return runnerPreferences()
	}

	return []string{runner}
}

func canonicalRunner(runner string) string {
	return strings.ToLower(strings.TrimSpace(runner))
}

// MetadataForConfig returns the default manifest-list runner and weight format
// for a model config. It is intentionally conservative: GGUF models created by
// the legacy path are tagged ggml, while converted GGUF manifests can override
// the runner to llamacpp when they are written.
func MetadataForConfig(config model.ConfigV2) (runner, format string) {
	switch strings.ToLower(config.ModelFormat) {
	case FormatSafetensors:
		return RunnerMLX, FormatSafetensors
	case FormatGGUF, "ggml":
		return RunnerGGML, FormatGGUF
	default:
		return "", strings.ToLower(config.ModelFormat)
	}
}

// FillMetadataForConfig populates missing runner/format metadata using the
// model config without overwriting explicit manifest-list child metadata.
func FillMetadataForConfig(m *Manifest, config model.ConfigV2) {
	runner, format := MetadataForConfig(config)
	if m.Runner == "" {
		m.Runner = runner
	} else {
		m.Runner = canonicalRunner(m.Runner)
	}
	if m.Format == "" {
		m.Format = format
	} else {
		m.Format = strings.ToLower(strings.TrimSpace(m.Format))
	}
}

// FillMetadata populates missing runner/format metadata by reading the
// manifest's config blob, and canonicalizes what is already present. It
// returns an error when the metadata cannot be determined.
func FillMetadata(m *Manifest) error {
	if m.Runner != "" && m.Format != "" {
		m.Runner = canonicalRunner(m.Runner)
		m.Format = strings.ToLower(strings.TrimSpace(m.Format))
		return nil
	}

	config, err := readConfigV2(m.Config.Digest)
	if err != nil {
		return err
	}
	FillMetadataForConfig(m, config)
	if m.Runner == "" || m.Format == "" {
		return errors.New("manifest is missing runner or format metadata")
	}
	return nil
}

func readConfigV2(digest string) (model.ConfigV2, error) {
	var config model.ConfigV2
	if digest == "" {
		return config, errors.New("manifest is missing config digest")
	}

	configPath, err := BlobsPath(digest)
	if err != nil {
		return config, err
	}
	f, err := os.Open(configPath)
	if err != nil {
		return config, err
	}
	defer f.Close()

	return config, json.NewDecoder(f).Decode(&config)
}

func parseManifest(data []byte) (*Manifest, error) {
	var m Manifest
	if err := json.Unmarshal(data, &m); err != nil {
		return nil, err
	}
	if m.MediaType == MediaTypeManifestList {
		for i := range m.Manifests {
			if m.Manifests[i].MediaType == MediaTypeManifestList {
				return nil, errors.New("nested manifest lists are not supported")
			}
			if m.Manifests[i].isReference() {
				continue
			}

			canonical, err := json.Marshal(m.Manifests[i])
			if err != nil {
				return nil, err
			}
			sum := sha256.Sum256(canonical)
			m.Manifests[i].digest = fmt.Sprintf("%x", sum)
		}
	}

	return &m, nil
}

func readManifestBlob(digest string) ([]byte, error) {
	digest, err := canonicalBlobDigest(digest)
	if err != nil {
		return nil, err
	}

	blobPath, err := BlobsPath(digest)
	if err != nil {
		return nil, err
	}

	data, err := os.ReadFile(blobPath)
	if err != nil {
		return nil, err
	}
	if err := checkBlobDigestReader(bytes.NewReader(data), digest); err != nil {
		return nil, err
	}

	return data, nil
}

func parseManifestBlobIfExists(digest string) (*Manifest, bool, error) {
	data, err := readManifestBlob(digest)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, false, nil
		}
		return nil, false, err
	}

	m, err := parseManifest(data)
	if err != nil {
		return nil, false, err
	}

	return m, true, nil
}

func canonicalBlobDigest(digest string) (string, error) {
	if _, err := BlobsPath(digest); err != nil {
		return "", err
	}

	return NormalizeDigest(digest), nil
}

// NormalizeDigest canonicalizes a blob digest for comparison: lowercase, with
// the filesystem's "sha256-" separator spelling folded to "sha256:". It does
// not validate the digest.
func NormalizeDigest(digest string) string {
	return strings.ToLower(strings.Replace(strings.TrimSpace(digest), "-", ":", 1))
}

// SameDigest reports whether two blob digests refer to the same content,
// tolerating case, separator, and bare-hex spelling differences.
func SameDigest(a, b string) bool {
	return a != "" && blobDigest(NormalizeDigest(a)) == blobDigest(NormalizeDigest(b))
}

func blobDigest(digest string) string {
	if digest == "" {
		return ""
	}

	digest = strings.ToLower(digest)
	if strings.HasPrefix(digest, "sha256:") || strings.HasPrefix(digest, "sha256-") {
		return digest
	}

	return "sha256:" + digest
}

func WriteManifest(name model.Name, config Layer, layers []Layer) error {
	return WriteManifestWithMetadata(name, config, layers, "", "")
}

// WriteManifestWithMetadata stores a single runnable manifest with optional
// runner and weight format metadata.
func WriteManifestWithMetadata(name model.Name, config Layer, layers []Layer, runner, format string) error {
	m := Manifest{
		SchemaVersion: 2,
		MediaType:     MediaTypeManifest,
		Config:        config,
		Layers:        layers,
		Runner:        canonicalRunner(runner),
		Format:        format,
	}

	var b bytes.Buffer
	if err := json.NewEncoder(&b).Encode(m); err != nil {
		return err
	}

	return WriteManifestData(name, b.Bytes())
}

// NewManifestReference returns a manifest-list entry that points at an existing
// child manifest blob.
func NewManifestReference(digest, runner, format string) (Manifest, error) {
	digest, err := canonicalBlobDigest(digest)
	if err != nil {
		return Manifest{}, err
	}

	return Manifest{
		MediaType: MediaTypeManifest,
		Runner:    canonicalRunner(runner),
		Format:    format,
		digest:    strings.TrimPrefix(digest, "sha256:"),
	}, nil
}

// WriteManifestBlob stores raw manifest bytes as a content-addressed blob.
func WriteManifestBlob(data []byte) (string, error) {
	return writeManifestBlob(data)
}

// WriteManifestData stores raw manifest bytes as a content-addressed blob and
// updates the v2 named manifest path to reference that blob. Any legacy named
// manifest for the same model is removed after the v2 write succeeds.
func WriteManifestData(name model.Name, data []byte) error {
	return writeManifestData(name, data, true)
}

// WriteManifestDataPreserveLegacy updates the v2 named manifest path without
// removing legacy manifest entries for the same model.
func WriteManifestDataPreserveLegacy(name model.Name, data []byte) error {
	return writeManifestData(name, data, false)
}

// WriteManifestList stores a manifest list referencing refs under name. It
// returns the digest of the stored manifest-list document blob.
func WriteManifestList(name model.Name, refs []Manifest) (string, error) {
	return writeManifestList(name, refs, false)
}

// WriteManifestListPreserveLegacy stores a manifest list while keeping any
// legacy named manifest for the same model in place as a downgrade anchor. It
// returns the digest of the stored manifest-list document blob.
func WriteManifestListPreserveLegacy(name model.Name, refs []Manifest) (string, error) {
	return writeManifestList(name, refs, true)
}

func writeManifestList(name model.Name, refs []Manifest, preserveLegacy bool) (string, error) {
	parent := Manifest{
		SchemaVersion: 2,
		MediaType:     MediaTypeManifestList,
		Manifests:     refs,
	}
	data, err := json.Marshal(parent)
	if err != nil {
		return "", err
	}
	digest := fmt.Sprintf("sha256:%x", sha256.Sum256(data))
	if preserveLegacy {
		return digest, WriteManifestDataPreserveLegacy(name, data)
	}
	return digest, WriteManifestData(name, data)
}

func writeManifestData(name model.Name, data []byte, removeLegacy bool) error {
	if !name.IsFullyQualified() {
		return model.Unqualified(name)
	}

	manifestStoreMu.Lock()
	defer manifestStoreMu.Unlock()

	digest, err := writeManifestBlob(data)
	if err != nil {
		return err
	}

	if err := linkManifest(name, digest); err != nil {
		return err
	}

	if !removeLegacy {
		return nil
	}

	return removeLegacyManifestPaths(name)
}

// WriteLegacyAnchor writes mf as a legacy manifest at name with the v2
// manifest blobs named by manifestDigests appended as layers. The extra layers
// exist only so a pre-manifest-list daemon's garbage collector, which retains
// just the digests listed by legacy manifests, cannot delete the manifest
// blobs during a downgrade.
func WriteLegacyAnchor(name model.Name, mf *Manifest, manifestDigests ...string) error {
	if mf == nil {
		return errors.New("downgrade anchor requires a manifest")
	}

	anchor := *mf
	anchor.Layers = slices.Clone(mf.Layers)
	for _, manifestDigest := range manifestDigests {
		digest, err := canonicalBlobDigest(manifestDigest)
		if err != nil {
			return err
		}
		data, err := readManifestBlob(digest)
		if err != nil {
			return err
		}
		mediaType := MediaTypeManifest
		var m Manifest
		if err := json.Unmarshal(data, &m); err == nil && m.MediaType == MediaTypeManifestList {
			mediaType = MediaTypeManifestList
		}
		anchor.Layers = append(anchor.Layers, Layer{
			MediaType: mediaType,
			Digest:    digest,
			Size:      int64(len(data)),
		})
	}

	data, err := json.Marshal(anchor)
	if err != nil {
		return err
	}

	return WriteLegacyManifestData(name, data)
}

// WriteLegacyManifestData stores raw manifest bytes in the legacy named
// manifest tree for compatibility with older Ollama releases.
func WriteLegacyManifestData(name model.Name, data []byte) error {
	if !name.IsFullyQualified() {
		return model.Unqualified(name)
	}

	manifestStoreMu.Lock()
	defer manifestStoreMu.Unlock()

	name = normalizeLogicalName(name)
	if !legacyManifestPathSupported(name) {
		return nil
	}

	manifestPath, err := LegacyPathForName(name)
	if err != nil {
		return err
	}
	if err := os.MkdirAll(filepath.Dir(manifestPath), 0o755); err != nil {
		return err
	}

	temp, err := os.CreateTemp(filepath.Dir(manifestPath), ".manifest-*")
	if err != nil {
		return err
	}
	tempName := temp.Name()
	defer os.Remove(tempName)

	if _, err := temp.Write(data); err != nil {
		temp.Close()
		return err
	}
	if err := temp.Close(); err != nil {
		return err
	}
	if err := os.Chmod(tempName, 0o644); err != nil {
		return err
	}

	return replaceManifestPath(tempName, manifestPath)
}

func linkManifest(name model.Name, digest string) error {
	manifestPath, err := V2PathForName(name)
	if err != nil {
		return err
	}
	blobPath, err := BlobsPath(digest)
	if err != nil {
		return err
	}
	if _, err := os.Stat(blobPath); err != nil {
		return err
	}
	if err := checkBlobDigest(blobPath, digest); err != nil {
		return err
	}

	if err := os.MkdirAll(filepath.Dir(manifestPath), 0o755); err != nil {
		return err
	}

	// Avoid symlinks on windows
	if runtime.GOOS == "windows" {
		return copyManifestFile(blobPath, manifestPath)
	}

	if rel, err := filepath.Rel(filepath.Dir(manifestPath), blobPath); err == nil {
		tempName, err := tempManifestPath(filepath.Dir(manifestPath))
		if err != nil {
			return err
		}
		defer os.Remove(tempName)
		if err := os.Symlink(rel, tempName); err == nil {
			return replaceManifestPath(tempName, manifestPath)
		}
	}

	return copyManifestFile(blobPath, manifestPath)
}

func writeManifestBlob(data []byte) (string, error) {
	sum := sha256.Sum256(data)
	digest := fmt.Sprintf("sha256:%x", sum)

	blobPath, err := BlobsPath(digest)
	if err != nil {
		return "", err
	}
	if existing, err := os.ReadFile(blobPath); err == nil && bytes.Equal(existing, data) {
		return digest, nil
	}

	blobs, err := BlobsPath("")
	if err != nil {
		return "", err
	}
	temp, err := os.CreateTemp(blobs, "sha256-")
	if err != nil {
		return "", err
	}
	tempName := temp.Name()
	defer os.Remove(tempName)

	if _, err := temp.Write(data); err != nil {
		temp.Close()
		return "", err
	}
	if err := temp.Close(); err != nil {
		return "", err
	}
	if err := os.Chmod(tempName, 0o644); err != nil {
		return "", err
	}
	if err := os.Rename(tempName, blobPath); err != nil {
		// Accept a racing identical blob; otherwise leave it untouched.
		if existing, readErr := os.ReadFile(blobPath); readErr == nil && bytes.Equal(existing, data) {
			return digest, nil
		}
		return "", err
	}

	return digest, nil
}

func copyManifestFile(src, dst string) error {
	in, err := os.Open(src)
	if err != nil {
		return err
	}
	defer in.Close()

	temp, err := os.CreateTemp(filepath.Dir(dst), ".manifest-*")
	if err != nil {
		return err
	}
	tempName := temp.Name()
	defer os.Remove(tempName)

	if _, err := io.Copy(temp, in); err != nil {
		temp.Close()
		return err
	}
	if err := temp.Close(); err != nil {
		return err
	}
	if err := os.Chmod(tempName, 0o644); err != nil {
		return err
	}

	return replaceManifestPath(tempName, dst)
}

func tempManifestPath(dir string) (string, error) {
	temp, err := os.CreateTemp(dir, ".manifest-*")
	if err != nil {
		return "", err
	}
	tempName := temp.Name()
	if err := temp.Close(); err != nil {
		os.Remove(tempName)
		return "", err
	}
	if err := os.Remove(tempName); err != nil {
		return "", err
	}

	return tempName, nil
}

func replaceManifestPath(tempName, dst string) error {
	if err := os.Rename(tempName, dst); err == nil {
		return nil
	} else if runtime.GOOS != "windows" {
		return err
	}

	// Windows does not replace an existing destination with Rename. The store
	// mutex keeps this path safe within a process; callers still prepare the new
	// ref before the old one is removed.
	if err := os.Remove(dst); err != nil && !os.IsNotExist(err) {
		return err
	}

	return os.Rename(tempName, dst)
}

// OpenVerifiedManifest opens a named manifest path rooted under root. Symlinks must resolve to a
// blob whose basename is sha256-<hex> and whose bytes hash to that digest.
// Regular-file manifests are treated as legacy/copy fallback manifests and are
// opened without mutating the local store. Their returned digest identifies the
// bytes read; regular files have no expected digest to compare against.
func OpenVerifiedManifest(path, root string) (*os.File, string, error) {
	manifestStoreMu.Lock()
	defer manifestStoreMu.Unlock()
	return openVerifiedManifestLocked(path, root)
}

// NamedManifestPointsToDigest reports whether the v2 name is a symlink to the
// given content-addressed manifest blob. It checks the link and target without
// reading or hashing the blob. Legacy and copied manifests return false so
// callers can use full validation instead.
func NamedManifestPointsToDigest(n model.Name, digest string) bool {
	if !n.IsFullyQualified() || ValidateDigest("sha256:"+digest) != nil {
		return false
	}
	path, err := V2PathForName(n)
	if err != nil {
		return false
	}
	blobPath, err := BlobsPath("sha256:" + digest)
	if err != nil {
		return false
	}

	manifestStoreMu.Lock()
	defer manifestStoreMu.Unlock()

	info, err := os.Lstat(path)
	if err != nil || info.Mode()&os.ModeSymlink == 0 {
		return false
	}
	target, err := evalAbs(path)
	if err != nil || !strings.EqualFold(filepath.Base(target), "sha256-"+digest) {
		return false
	}
	return sameFile(target, blobPath)
}

func openVerifiedManifestLocked(path, root string) (*os.File, string, error) {
	opened, err := openManifestFileLocked(path, root)
	if err != nil {
		return nil, "", err
	}
	return opened.verifiedFile()
}

// unverifiedManifestFile keeps the opened bytes with the digest required for
// a content-addressed symlink. Regular files have no expected digest; their
// contents are hashed to establish their identity when read.
type unverifiedManifestFile struct {
	file           *os.File
	expectedDigest string
}

func (m *unverifiedManifestFile) checkDigest(digest string) error {
	if m.expectedDigest != "" && digest != m.expectedDigest {
		return errors.New("digest mismatch")
	}
	return nil
}

// verifiedFile returns a rewound file after checking all its bytes. The caller
// owns the returned file.
func (m *unverifiedManifestFile) verifiedFile() (*os.File, string, error) {
	h := sha256.New()
	if _, err := io.Copy(h, m.file); err != nil {
		m.file.Close()
		return nil, "", err
	}
	digest := fmt.Sprintf("%x", h.Sum(nil))
	if err := m.checkDigest(digest); err != nil {
		m.file.Close()
		return nil, "", err
	}
	if _, err := m.file.Seek(0, io.SeekStart); err != nil {
		m.file.Close()
		return nil, "", err
	}
	return m.file, digest, nil
}

// verifiedData reads and checks the file in one pass, then closes it.
func (m *unverifiedManifestFile) verifiedData() ([]byte, string, error) {
	defer m.file.Close()
	data, err := io.ReadAll(m.file)
	if err != nil {
		return nil, "", err
	}
	sum := sha256.Sum256(data)
	digest := fmt.Sprintf("%x", sum)
	if err := m.checkDigest(digest); err != nil {
		return nil, "", err
	}
	return data, digest, nil
}

// openManifestFileLocked checks the named path before opening its contents.
// Only the verification methods expose the contents to callers.
func openManifestFileLocked(path, root string) (*unverifiedManifestFile, error) {
	resolvedRoot, err := filepath.EvalSymlinks(root)
	if err != nil {
		return nil, err
	}

	info, err := os.Lstat(path)
	if err != nil {
		return nil, err
	}

	target, err := evalAbs(path)
	if err != nil {
		return nil, err
	}

	if info.Mode()&os.ModeSymlink != 0 {
		base := filepath.Base(target)
		if !blobFilenamePattern.MatchString(base) {
			return nil, fmt.Errorf("manifest symlink target %q is not a sha256 blob", target)
		}

		digest := strings.ToLower(strings.TrimPrefix(base, "sha256-"))
		blobPath, err := BlobsPath("sha256:" + digest)
		if err != nil {
			return nil, err
		}
		if !sameFile(target, blobPath) {
			return nil, fmt.Errorf("manifest symlink target %q does not match blob %q", target, blobPath)
		}

		readPath := path
		if runtime.GOOS == "windows" {
			readPath = blobPath
		}
		f, err := os.Open(readPath)
		if err != nil {
			return nil, err
		}
		if runtime.GOOS == "windows" {
			if err := checkBlobDigestReader(f, "sha256:"+digest); err != nil {
				f.Close()
				return nil, err
			}
			if _, err := f.Seek(0, io.SeekStart); err != nil {
				f.Close()
				return nil, err
			}
			if err := copyManifestFile(blobPath, path); err != nil {
				slog.Warn("could not replace manifest symlink", "path", path, "error", err)
			}
		}

		return &unverifiedManifestFile{file: f, expectedDigest: digest}, nil
	}

	if !pathWithin(target, resolvedRoot) {
		return nil, fmt.Errorf("manifest path %q resolves outside manifest directory", path)
	}

	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}

	return &unverifiedManifestFile{file: f}, nil
}

// MigrateManifestLinks moves legacy named manifests into manifests-v2. This is currently unwired but
// will be added in the future.
func MigrateManifestLinks() (int, error) {
	manifests, err := Path()
	if err != nil {
		return 0, err
	}

	// TODO(mxyng): use something less brittle
	matches, err := filepath.Glob(filepath.Join(manifests, "*", "*", "*", "*"))
	if err != nil {
		return 0, err
	}

	var migrated int
	for _, match := range matches {
		fi, err := os.Stat(match)
		if err != nil {
			return migrated, err
		}
		if fi.IsDir() {
			continue
		}

		rel, err := filepath.Rel(manifests, match)
		if err != nil {
			return migrated, fmt.Errorf("%s %w", match, err)
		}

		n := model.ParseNameFromFilepath(rel)
		if !n.IsFullyQualified() {
			slog.Warn("bad manifest name", "path", rel)
			continue
		}

		data, err := readManifestPath(match, manifests)
		if err != nil {
			return migrated, err
		}
		if err := WriteManifestData(normalizeLogicalName(n), data); err != nil {
			return migrated, err
		}
		migrated++
	}

	return migrated, nil
}

func readManifestPath(path, root string) ([]byte, error) {
	data, _, _, err := readVerifiedManifest(path, root)
	return data, err
}

func readVerifiedManifest(path, root string) ([]byte, os.FileInfo, string, error) {
	manifestStoreMu.Lock()
	defer manifestStoreMu.Unlock()
	return readVerifiedManifestLocked(path, root)
}

func readVerifiedManifestLocked(path, root string) ([]byte, os.FileInfo, string, error) {
	opened, err := openManifestFileLocked(path, root)
	if err != nil {
		return nil, nil, "", err
	}

	data, digest, err := opened.verifiedData()
	if err != nil {
		return nil, nil, "", err
	}
	fi, err := os.Lstat(path)
	if err != nil {
		return nil, nil, "", err
	}

	return data, fi, digest, nil
}

func pathWithin(path, root string) bool {
	rel, err := filepath.Rel(root, path)
	return err == nil && rel != "." && !strings.HasPrefix(rel, ".."+string(filepath.Separator)) && rel != ".."
}

func evalAbs(path string) (string, error) {
	abs, err := filepath.Abs(path)
	if err != nil {
		return "", err
	}
	return filepath.EvalSymlinks(abs)
}

func sameFile(a, b string) bool {
	ai, err := os.Stat(a)
	if err != nil {
		return false
	}
	bi, err := os.Stat(b)
	if err != nil {
		return false
	}
	return os.SameFile(ai, bi)
}

func checkBlobDigest(path, digest string) error {
	f, err := os.Open(path)
	if err != nil {
		return err
	}
	defer f.Close()

	return checkBlobDigestReader(f, digest)
}

func checkBlobDigestReader(r io.Reader, digest string) error {
	h := sha256.New()
	if _, err := io.Copy(h, r); err != nil {
		return err
	}

	got := fmt.Sprintf("sha256:%x", h.Sum(nil))
	if got != strings.ToLower(strings.Replace(digest, "-", ":", 1)) {
		return errors.New("digest mismatch")
	}

	return nil
}

// FindName returns the stored spelling of a case-insensitive name match, or
// os.ErrNotExist. Like Manifests, it ignores invalid manifests and prefers v2
// entries, but only reads manifest contents for matching names.
func FindName(n model.Name) (model.Name, error) {
	refs, err := namedManifestRefs(true)
	if err != nil {
		return model.Name{}, err
	}

	for name, ref := range refs {
		if name.EqualFold(n) {
			if _, err := parseManifestFile(name, ref.path, ref.root, runnerPreferences()); err == nil {
				return name, nil
			}
		}
	}
	return model.Name{}, os.ErrNotExist
}

// FindNamedManifestForRunner finds a named model case-insensitively and returns
// its verified, runner-selected manifest. It reports an invalid matching
// manifest when no valid selection exists.
func FindNamedManifestForRunner(n model.Name, runner string) (*Manifest, error) {
	refs, err := namedManifestRefs(true)
	if err != nil {
		return nil, err
	}

	var invalid, noCompatible error
	for name, ref := range refs {
		if !name.EqualFold(n) {
			continue
		}
		selected, err := parseManifestFile(name, ref.path, ref.root, runnerPreferencesFor(runner))
		if err == nil {
			return selected, nil
		} else if errors.Is(err, ErrNoCompatibleManifest) {
			noCompatible = err
		} else if invalid == nil {
			invalid = err
		}
	}
	if invalid != nil {
		return nil, invalid
	}
	if noCompatible != nil {
		return nil, noCompatible
	}
	return nil, os.ErrNotExist
}

func Manifests(continueOnError bool) (map[model.Name]*Manifest, error) {
	refs, err := namedManifestRefs(continueOnError)
	if err != nil {
		return nil, err
	}

	ms := make(map[model.Name]*Manifest, len(refs))
	for n, ref := range refs {
		m, err := parseManifestFile(n, ref.path, ref.root, runnerPreferences())
		if err != nil {
			if !continueOnError {
				return nil, fmt.Errorf("%s %w", n, err)
			}
			slog.Warn("bad manifest", "name", n, "error", err)
			continue
		}

		ms[n] = m
	}
	return ms, nil
}

type namedManifestRef struct {
	path string
	root string
}

func namedManifestRefs(continueOnError bool) (map[model.Name]namedManifestRef, error) {
	refs := make(map[model.Name]namedManifestRef)

	manifestsV2, err := V2Path()
	if err != nil {
		return nil, err
	}
	if err := collectManifestRefs(refs, manifestsV2, continueOnError); err != nil {
		return nil, err
	}

	manifests, err := Path()
	if err != nil {
		return nil, err
	}
	if err := collectManifestRefs(refs, manifests, continueOnError); err != nil {
		return nil, err
	}

	return refs, nil
}

func collectManifestRefs(refs map[model.Name]namedManifestRef, root string, continueOnError bool) error {
	// TODO(mxyng): use something less brittle
	matches, err := filepath.Glob(filepath.Join(root, "*", "*", "*", "*"))
	if err != nil {
		return err
	}

	for _, match := range matches {
		fi, err := os.Lstat(match)
		if err != nil {
			return err
		}

		if !fi.IsDir() {
			rel, err := filepath.Rel(root, match)
			if err != nil {
				if !continueOnError {
					return fmt.Errorf("%s %w", match, err)
				}
				slog.Warn("bad filepath", "path", match, "error", err)
				continue
			}

			n := parseStoredManifestFilepath(rel)
			if !n.IsValid() {
				if !continueOnError {
					return fmt.Errorf("invalid manifest name: %s", rel)
				}
				slog.Warn("bad manifest name", "path", rel)
				continue
			}

			n = normalizeLogicalName(n)
			if _, ok := refs[n]; ok {
				continue
			}

			refs[n] = namedManifestRef{path: match, root: root}
		}
	}

	return nil
}
