// ErrIncompleteAudit is returned when a reclamation cannot run safely because
// the snapshot could not see the whole store.
var ErrIncompleteAudit = errors.New("audit incomplete; refusing to reclaim while parts of the store are unreadable")

// defaultMinTempAge mirrors the historical grace period: an unlocked staging
// file younger than this is left alone even with no active claim.
func layerPruneMinTempAge() time.Duration { return time.Hour }

func jsonUnmarshalManifest(data []byte, m *Manifest) error {
	return json.Unmarshal(data, m)
}

// ReclaimResult reports what one reclamation actually did. Repeated runs
// converge: blobs already gone are not counted twice.
type ReclaimResult struct {
	// RemovedBlobs are content-addressed orphans that were deleted.
	RemovedBlobs []string `json:"removedBlobs"`
	// RemovedTemps are abandoned partial/staging files that were deleted.
	RemovedTemps []string `json:"removedTemps"`
	// Quarantined are manifests moved aside during the audit.
	Quarantined []QuarantineEntry `json:"quarantined"`
	// InUse lists digests skipped because a write is in progress.
	InUse []string `json:"inUse"`
	// Failed lists objects that could not be removed and why.
	Failed []LayerIssue `json:"failed"`
	// ReclaimedBytes is the total size actually freed.
	ReclaimedBytes int64 `json:"reclaimedBytes"`
	// Incomplete mirrors the snapshot flag; when true nothing was deleted.
	Incomplete bool `json:"incomplete"`
}

// AuditAndQuarantine takes a snapshot, moves every untrusted manifest into the
// quarantine directory, and returns the snapshot. Quarantine happens before
// any reclamation decision, and quarantined references are retained.
func AuditAndQuarantine(opts AuditOptions) (*Snapshot, error) {
	manifestStoreMu.Lock()
	defer manifestStoreMu.Unlock()

	snap, err := takeSnapshotLocked(opts)
	if err != nil {
		return nil, err
	}

	if err := quarantineBadManifests(snap); err != nil {
		return snap, err
	}

	// Byte verification opens files read-only and tolerates concurrent
	// replacement, so it does not need the store mutex held.
	manifestStoreMu.Unlock()
	if opts.VerifyBytes {
		verifySnapshotBlobs(snap, opts)
	}
	computeReclaimEstimate(snap, opts)
	manifestStoreMu.Lock()
	return snap, nil
}

// quarantineBadManifests moves each manifest recorded as untrusted into
// quarantine. Re-quarantining the same origin is idempotent.
func quarantineBadManifests(snap *Snapshot) error {
	refs, err := namedManifestRefs(true)
	if err != nil {
		return err
	}

	for _, issue := range snap.ManifestIssues {
		ref, ok := refs[issue.Model]
		if !ok {
			continue
		}
		rel, err := filepath.Rel(ref.root, ref.path)
		if err != nil {
			return err
		}
		raw, fileErr := os.ReadFile(ref.path)
		var references []string
		if fileErr == nil {
			references = salvageDigests(raw)
		}
		entry, qerr := quarantineManifest(rel, ref.root, issue.Reason, references)
		if qerr != nil {
			slog.Warn("quarantine failed", "name", issue.Model, "error", qerr)
			snap.Inaccessible = append(snap.Inaccessible, qerr.Error())
			continue
		}
		snap.Quarantine = append(snap.Quarantine, entry)
		for _, d := range entry.References {
			snap.QuarantineRefs[d] = struct{}{}
		}
		// The manifest no longer exists as a named entry; drop its model row.
		delete(snap.Models, issue.Model)
		delete(snap.ModelBlobs, issue.Model)
	}

	if err := pruneManifestRoots(); err != nil && !os.IsNotExist(err) {
		slog.Warn("prune manifest directories after quarantine", "error", err)
	}
	return nil
}

// Reclaim performs the full governance pass from one snapshot: quarantine bad
// manifests, then delete only orphaned blobs and abandoned staging files.
// Shared blobs are never touched because their reference count is nonzero.
//
// The store mutex serializes the structural parts against manifest writes and
// deletes. An incomplete snapshot deletes nothing; an ENOSPC or other removal
// error is reported per object with the store left readable and never
// half-deleted.
func Reclaim(opts AuditOptions) (*ReclaimResult, error) {
	manifestStoreMu.Lock()
	snap, err := takeSnapshotLocked(opts)
	if err != nil {
		manifestStoreMu.Unlock()
		return nil, err
	}
	if err := quarantineBadManifests(snap); err != nil {
		manifestStoreMu.Unlock()
		return nil, err
	}
	manifestStoreMu.Unlock()

	if opts.VerifyBytes {
		verifySnapshotBlobs(snap, opts)
	}
	computeReclaimEstimate(snap, opts)

	return ReclaimSnapshot(snap)
}

// ReclaimSnapshot reclaims based on an existing snapshot. Recomputing the
// reference set immediately before each removal keeps a concurrent manifest
// write from making a blob newly-orphaned in a way the snapshot did not see;
// the store mutex makes that recompute authoritative.
func ReclaimSnapshot(snap *Snapshot) (*ReclaimResult, error) {
	result := &ReclaimResult{Incomplete: snap.Incomplete}
	if snap.Incomplete {
		return result, ErrIncompleteAudit
	}

	manifestStoreMu.Lock()
	defer manifestStoreMu.Unlock()

	// Re-derive the live retained set under the lock so a manifest written
	// after the snapshot still protects its blobs. Quarantine references are
	// included explicitly.
	retained, err := retainedBlobDigestsLocked()
	if err != nil {
		return result, err
	}
	for d := range snap.QuarantineRefs {
		if ValidateDigest(d) == nil {
			retained[d] = struct{}{}
		}
	}

	// Stable removal order makes the result deterministic and testable.
	orphans := append([]string(nil), snap.Orphans...)
	sort.Strings(orphans)

	for _, digest := range orphans {
		if _, keep := retained[digest]; keep {
			continue
		}
		if IsBlobInUse(digest) {
			result.InUse = append(result.InUse, digest)
			continue
		}
		path, err := BlobsPath(digest)
		if err != nil {
			result.Failed = append(result.Failed, LayerIssue{Digest: digest, Reason: err.Error()})
			continue
		}
		info, statErr := os.Stat(path)
		if os.IsNotExist(statErr) {
			continue // already reclaimed; convergence, not an error
		}
		if err := os.Remove(path); err != nil {
			if os.IsNotExist(err) {
				continue
			}
			result.Failed = append(result.Failed, LayerIssue{
				Digest: digest,
				Size:   info.Size(),
				Reason: removalReason(err),
			})
			if isNoSpace(err) {
				// Stop at the first ENOSPC: further removals cannot help and
				// every object still on disk remains accounted for.
				break
			}
			continue
		}
		result.RemovedBlobs = append(result.RemovedBlobs, digest)
		result.ReclaimedBytes += info.Size()
	}

	// Abandoned staging files: only those the snapshot classified as
	// reclaimable, and only if no claim has appeared since.
	for _, temp := range snap.Temps {
		if !temp.Reclaimable {
			continue
		}
		if temp.Digest != "" && IsBlobInUse(temp.Digest) {
			result.InUse = append(result.InUse, temp.Digest)
			continue
		}
		info, statErr := os.Stat(temp.Path)
		if os.IsNotExist(statErr) {
			continue
		}
		if err := os.Remove(temp.Path); err != nil {
			if os.IsNotExist(err) {
				continue
			}
			result.Failed = append(result.Failed, LayerIssue{
				Digest: temp.Digest,
				Size:   temp.Size,
				Reason: removalReason(err),
			})
			if isNoSpace(err) {
				break
			}
			continue
		}
		result.RemovedTemps = append(result.RemovedTemps, temp.Path)
		result.ReclaimedBytes += temp.Size
	}

	return result, nil
}

func removalReason(err error) string {
	if isNoSpace(err) {
		return "no space left on device; object not reclaimed"
	}
	if errors.Is(err, os.ErrPermission) {
		return "permission denied; store may be read-only"
	}
	return fmt.Sprintf("remove failed: %v", err)
}

func isNoSpace(err error) bool {
	return errors.Is(err, syscall.ENOSPC)
}

// VerifyModel checks every config and layer blob a named model needs before
// it is loaded or served. A missing or non-matching blob produces an error
// naming the model and the specific layer and marks the model unavailable.
// Verification is streamed with bounded memory.
func VerifyModel(n model.Name, chunkSize int) error {
	if chunkSize <= 0 {
		chunkSize = DefaultAuditChunkSize
	}

	data, err := ReadManifestData(n)
	if err != nil {
		return &ModelUnavailableError{Model: n.DisplayShortest(), Reason: fmt.Sprintf("manifest unreadable: %v", err)}
	}

	var m Manifest
	if err := json.Unmarshal(data, &m); err != nil {
		return &ModelUnavailableError{Model: n.DisplayShortest(), Reason: fmt.Sprintf("manifest unparseable: %v", err)}
	}

	layers := append([]Layer{}, m.Layers...)
	if m.Config.Digest != "" {
		layers = append(layers, m.Config)
	}

	seen := make(map[string]struct{})
	for _, layer := range layers {
		if layer.Digest == "" {
			continue
		}
		digest := NormalizeDigest(layer.Digest)
		if _, dup := seen[digest]; dup {
			continue
		}
		seen[digest] = struct{}{}

		path, err := BlobsPath(digest)
		if err != nil {
			return &ModelUnavailableError{Model: n.DisplayShortest(), Layer: digest, Reason: err.Error()}
		}
		info, err := os.Stat(path)
		if err != nil {
			return &ModelUnavailableError{
				Model: n.DisplayShortest(), Layer: digest,
				Reason: "layer missing from store",
			}
		}
		if layer.Size > 0 && info.Size() != layer.Size {
			return &ModelUnavailableError{
				Model: n.DisplayShortest(), Layer: digest,
				Reason: fmt.Sprintf("size mismatch: on disk %d, declared %d", info.Size(), layer.Size),
			}
		}
		if err := checkBlobDigestChunked(path, digest, chunkSize); err != nil {
			return &ModelUnavailableError{
				Model: n.DisplayShortest(), Layer: digest,
				Reason: err.Error(),
			}
		}
	}
	return nil
}

// ModelUnavailableError names both the model and the layer that failed
// pre-use verification, so callers never surface a generic load failure.
type ModelUnavailableError struct {
	Model  string `json:"model"`
	Layer  string `json:"layer,omitempty"`
	Reason string `json:"reason"`
}

func (e *ModelUnavailableError) Error() string {
	if e.Layer == "" {
		return fmt.Sprintf("model %s unavailable: %s", e.Model, e.Reason)
	}
	return fmt.Sprintf("model %s unavailable: layer %s: %s", e.Model, e.Layer, e.Reason)
}

// IsModelUnavailable reports whether err marks a model as not servable.
func IsModelUnavailable(err error) bool {
	var target *ModelUnavailableError
	return errors.As(err, &target)
}

func checkBlobDigestChunked(path, digest string, chunkSize int) error {
	f, err := os.Open(path)
	if err != nil {
		return err
	}
	defer f.Close()
	return checkBlobDigestReaderBuffered(f, digest, chunkSize)
}

// RepairQuarantine removes a quarantine entry after its model has been either
// re-pulled (a healthy named manifest now references the same digests) or
// explicitly deleted. Subsequent Reclaim calls collect any digests whose
// reference count has reached zero.
func RepairQuarantine(modelName string) error {
	entries, err := listQuarantineEntries()
	if err != nil {
		return err
	}
	for _, entry := range entries {
		if entry.Model.DisplayShortest() == modelName || entry.Model.String() == modelName {
			return removeQuarantineEntry(entry)
		}
	}
	return os.ErrNotExist
}
