	// resumable partial files. A concurrent audit or reclaimer sees the claim
	// and leaves both the partial state and the final rename alone.
	claim, err := manifest.BeginBlobWrite(opts.digest)
	if err != nil {
		return false, err
	}
	defer claim.Release()

	data, ok := blobDownloadManager.LoadOrStore(opts.digest, &blobDownload{Name: fp, Digest: opts.digest})
	download := data.(*blobDownload)
	if !ok {
		requestURL := opts.n.BaseURL()
