		t.Fatal("shared blob wrongly reclaimed after model-c deletion")
	}

	// Idempotent convergence: a second run removes nothing new.
	result3, err := Reclaim(AuditOptions{Now: time.Now})
	if err != nil {
		t.Fatal(err)
	}
	if len(result3.RemovedBlobs) != 0 || len(result3.RemovedTemps) != 0 {
		t.Fatalf("second run must converge to no work, got blobs=%v temps=%v",
			result3.RemovedBlobs, result3.RemovedTemps)
	}
}

func TestSequentialAndConcurrentDeletesReclaimSharedOnce(t *testing.T) {
	t.Setenv("OLLAMA_MODELS", t.TempDir())
	d := buildThreeModelStore(t)

	// Sequential: delete both sharing models; shared blobs survive the first
	// delete and are reclaimed exactly once after the second.
	if _, err := RemoveNamed(model.ParseName("model-a")); err != nil {
		t.Fatal(err)
	}
	r1, err := Reclaim(AuditOptions{Now: time.Now})
	if err != nil {
		t.Fatal(err)
	}
	if !blobExists(t, d["shared1"]) {
		t.Fatal("shared blob must survive the first sharing model's deletion")
	}
	if contains(r1.RemovedBlobs, d["shared1"]) {
		t.Fatal("shared blob reclaimed while still referenced")
	}

	if _, err := RemoveNamed(model.ParseName("model-b")); err != nil {
		t.Fatal(err)
	}
	r2, err := Reclaim(AuditOptions{Now: time.Now})
	if err != nil {
		t.Fatal(err)
	}
	count := 0
	for _, rr := range [][]string{r2.RemovedBlobs} {
		for _, b := range rr {
			if b == d["shared1"] || b == d["shared2"] {
				count++
			}
		}
	}
	if count != 2 {
		t.Fatalf("expected both shared blobs reclaimed exactly once, got %d", count)
	}
	if blobExists(t, d["shared1"]) || blobExists(t, d["shared2"]) {
		t.Fatal("shared blobs remain after both sharing models deleted")
	}

	// Concurrent deletes on a fresh store must not double-reclaim or lose
	// data still referenced.
	t.Setenv("OLLAMA_MODELS", t.TempDir())
	d = buildThreeModelStore(t)

	done := make(chan error, 2)
	go func() { done <- deleteAndReclaim("model-a") }()
	go func() { done <- deleteAndReclaim("model-b") }()
	for range 2 {
		if err := <-done; err != nil {
			t.Fatal(err)
		}
	}

	// Final state: no manifest for a/b and their shared blobs gone exactly;
	// model-c and every blob it needs remain.
	for _, n := range []string{"model-a", "model-b", "model-c"} {
		_, err := ResolvePathForName(model.ParseName(n))
		if n == "model-c" && err != nil {
			t.Fatalf("model-c must remain: %v", err)
		}
	}
	if blobExists(t, d["shared1"]) {
		t.Fatal("shared blob remains after concurrent deletion of both owners")
	}
	if !blobExists(t, d["exclusive"]) || !blobExists(t, d["configC"]) {
		t.Fatal("model-c data lost during concurrent deletion")
	}
}

func deleteAndReclaim(name string) error {
	if _, err := RemoveNamed(model.ParseName(name)); err != nil {
		return err
	}
	_, err = Reclaim(AuditOptions{Now: time.Now})
	return err
}

