// writeTestBlob stores content as a content-addressed blob and returns its
// canonical digest and on-disk size.
func writeTestBlob(t *testing.T, content string) (string, int64) {
	t.Helper()
	layer, err := NewLayer(strings.NewReader(content), MediaTypeImageModel)
	if err != nil {
		t.Fatal(err)
	}
	return layer.Digest, layer.Size
}

func writeTestManifest(t *testing.T, name model.Name, config Layer, layers []Layer) {
	t.Helper()
	if err := WriteManifestWithMetadata(name, config, layers, RunnerLlamaCPP, FormatGGUF); err != nil {
		t.Fatal(err)
	}
}

func blobExists(t *testing.T, digest string) bool {
	t.Helper()
	p, err := BlobsPath(digest)
	if err != nil {
		t.Fatal(err)
	}
	_, err = os.Stat(p)
	return err == nil
}

// buildThreeModelStore builds the acceptance fixture:
//   - model-a and model-b share two layers (shared1, shared2)
//   - model-c owns one exclusive layer
//   - one corrupt manifest and two unfinished partial files are added
//
// It returns the digest map so assertions can name exact objects.
func buildThreeModelStore(t *testing.T) map[string]string {
	t.Helper()

	d := map[string]string{}
	d["shared1"], _ = writeTestBlob(t, "shared-layer-one")
	d["shared2"], _ = writeTestBlob(t, "shared-layer-two")
	d["exclusive"], _ = writeTestBlob(t, "exclusive-layer")
	d["configA"], _ = writeTestBlob(t, `{"model_type":"a"}`)
	d["configB"], _ = writeTestBlob(t, `{"model_type":"b"}`)
	d["configC"], _ = writeTestBlob(t, `{"model_type":"c"}`)

	writeTestManifest(t, model.ParseName("model-a"),
		Layer{MediaType: MediaTypeImageConfig, Digest: d["configA"], Size: blobSize(t, d["configA"])},
		[]Layer{
			{MediaType: MediaTypeImageModel, Digest: d["shared1"], Size: blobSize(t, d["shared1"])},
			{MediaType: MediaTypeImageModel, Digest: d["shared2"], Size: blobSize(t, d["shared2"])},
		})
	writeTestManifest(t, model.ParseName("model-b"),
		Layer{MediaType: MediaTypeImageConfig, Digest: d["configB"], Size: blobSize(t, d["configB"])},
		[]Layer{
			{MediaType: MediaTypeImageModel, Digest: d["shared1"], Size: blobSize(t, d["shared1"])},
			{MediaType: MediaTypeImageModel, Digest: d["shared2"], Size: blobSize(t, d["shared2"])},
		})
	writeTestManifest(t, model.ParseName("model-c"),
		Layer{MediaType: MediaTypeImageConfig, Digest: d["configC"], Size: blobSize(t, d["configC"])},
		[]Layer{
			{MediaType: MediaTypeImageModel, Digest: d["exclusive"], Size: blobSize(t, d["exclusive"])},
		})

	// Corrupt manifest: syntactically broken JSON at a valid named path.
	badPath, err := LegacyPathForName(model.ParseName("broken/model:latest"))
	if err != nil {
		t.Fatal(err)
	}
	if err := os.MkdirAll(filepath.Dir(badPath), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(badPath, []byte("{not valid json"), 0o644); err != nil {
		t.Fatal(err)
	}

	// Two unfinished partials, aged beyond the grace window.
	blobs, err := BlobsPath("")
	if err != nil {
		t.Fatal(err)
	}
	old := time.Now().Add(-2 * time.Hour)
	for _, name := range []string{
		"sha256-" + strings.Repeat("1", 64) + "-partial-0",
		"sha256-" + strings.Repeat("2", 64) + "-partial",
	} {
		p := filepath.Join(blobs, name)
		if err := os.WriteFile(p, []byte("partial"), 0o644); err != nil {
			t.Fatal(err)
		}
		if err := os.Chtimes(p, old, old); err != nil {
			t.Fatal(err)
		}
	}

	return d
}

func blobSize(t *testing.T, digest string) int64 {
	t.Helper()
	p, err := BlobsPath(digest)
	if err != nil {
		t.Fatal(err)
	}
	info, err := os.Stat(p)
	if err != nil {
		t.Fatal(err)
	}
	return info.Size()
}

func TestAuditAndReclaimSharedExclusiveAndPartials(t *testing.T) {
	t.Setenv("OLLAMA_MODELS", t.TempDir())
	d := buildThreeModelStore(t)

	// Full byte verification on the healthy models.
	snap, err := TakeSnapshot(AuditOptions{VerifyBytes: true, Now: time.Now})
	if err != nil {
		t.Fatal(err)
	}
	if len(snap.ManifestIssues) == 0 {
		t.Fatal("expected the corrupt manifest to be recorded as an issue")
	}
	if len(snap.Quarantine) != 0 {
		t.Fatalf("snapshot alone must not quarantine, got %d entries", len(snap.Quarantine))
	}

	// Reference counting: shared layers referenced twice, exclusive once.
	if ref := snap.Refs[d["shared1"]]; ref == nil || ref.References != 2 || !ref.Shared {
		t.Fatalf("shared1 refs = %+v, want 2 shared", ref)
	}
	if ref := snap.Refs[d["exclusive"]]; ref == nil || ref.References != 1 || ref.Shared {
		t.Fatalf("exclusive refs = %+v, want 1 non-shared", ref)
	}

	// Two aged partials must be classified reclaimable.
	if len(snap.Temps) < 2 {
		t.Fatalf("temps = %d, want at least 2", len(snap.Temps))
	}
	var reclaimableTemps int
	for _, temp := range snap.Temps {
		if temp.Reclaimable {
			reclaimableTemps++
		}
	}
	if reclaimableTemps != 2 {
		t.Fatalf("reclaimable temps = %d, want 2", reclaimableTemps)
	}

	// Reclaim: quarantine the bad manifest, keep shared blobs, drop partials.
	result, err := Reclaim(AuditOptions{Now: time.Now})
	if err != nil {
		t.Fatal(err)
	}
	if len(result.Quarantined) != 1 {
		t.Fatalf("quarantined = %d, want 1", len(result.Quarantined))
	}
	if len(result.RemovedTemps) != 2 {
		t.Fatalf("removed temps = %d, want 2", len(result.RemovedTemps))
	}
	// All model blobs still referenced, so no orphan removals yet.
	if len(result.RemovedBlobs) != 0 {
		t.Fatalf("removed blobs = %v, want none while models exist", result.RemovedBlobs)
	}
	if !blobExists(t, d["shared1"]) || !blobExists(t, d["shared2"]) {
		t.Fatal("shared blobs must survive reclamation")
	}
	if !blobExists(t, d["exclusive"]) {
		t.Fatal("exclusive blob must survive while model-c exists")
	}

	// Delete model-c: its exclusive layer is now orphaned and reclaimed once.
	if _, err := RemoveNamed(model.ParseName("model-c")); err != nil {
		t.Fatal(err)
	}
	result2, err := Reclaim(AuditOptions{Now: time.Now})
	if err != nil {
		t.Fatal(err)
	}
	if !contains(result2.RemovedBlobs, d["exclusive"]) {
		t.Fatalf("exclusive blob not reclaimed: %v", result2.RemovedBlobs)
	}
	if blobExists(t, d["exclusive"]) {
		t.Fatal("exclusive blob still present after model-c deletion")
	}
	if !blobExists(t, d["shared1"]) {
		t.Fatal("shared blob wrongly reclaimed after model-c deletion")
	}

	// Idempotent convergence: a second run removes nothing new.
	result3, err := Reclaim(AuditOptions{Now: time.Now})
	if err != nil {
		t.Fatal(err)
	}
	if len(result3.RemovedBlobs) != 0 || len(result3.RemovedTemps) != 0 {
		t.Fatalf("second run must converge to no work, got blobs=%v temps=%v",
			result3.RemovedBlobs, result3.RemovedTemps)
	}
}

func TestSequentialAndConcurrentDeletesReclaimSharedOnce(t *testing.T) {
	t.Setenv("OLLAMA_MODELS", t.TempDir())
	d := buildThreeModelStore(t)

	// Sequential: delete both sharing models; shared blobs survive the first
	// delete and are reclaimed exactly once after the second.
	if _, err := RemoveNamed(model.ParseName("model-a")); err != nil {
		t.Fatal(err)
	}
	r1, err := Reclaim(AuditOptions{Now: time.Now})
	if err != nil {
		t.Fatal(err)
	}
	if !blobExists(t, d["shared1"]) {
		t.Fatal("shared blob must survive the first sharing model's deletion")
	}
	if contains(r1.RemovedBlobs, d["shared1"]) {
		t.Fatal("shared blob reclaimed while still referenced")
	}

	if _, err := RemoveNamed(model.ParseName("model-b")); err != nil {
		t.Fatal(err)
	}
	r2, err := Reclaim(AuditOptions{Now: time.Now})
	if err != nil {
		t.Fatal(err)
	}
	count := 0
	for _, rr := range [][]string{r2.RemovedBlobs} {
		for _, b := range rr {
			if b == d["shared1"] || b == d["shared2"] {
				count++
			}
		}
	}
	if count != 2 {
		t.Fatalf("expected both shared blobs reclaimed exactly once, got %d", count)
	}
	if blobExists(t, d["shared1"]) || blobExists(t, d["shared2"]) {
		t.Fatal("shared blobs remain after both sharing models deleted")
	}

	// Concurrent deletes on a fresh store must not double-reclaim or lose
	// data still referenced.
	t.Setenv("OLLAMA_MODELS", t.TempDir())
	d = buildThreeModelStore(t)

	done := make(chan error, 2)
	go func() { done <- deleteAndReclaim("model-a") }()
	go func() { done <- deleteAndReclaim("model-b") }()
	for range 2 {
		if err := <-done; err != nil {
			t.Fatal(err)
		}
	}

	// Final state: no manifest for a/b and their shared blobs gone exactly;
	// model-c and every blob it needs remain.
	for _, n := range []string{"model-a", "model-b", "model-c"} {
		_, err := ResolvePathForName(model.ParseName(n))
		if n == "model-c" && err != nil {
			t.Fatalf("model-c must remain: %v", err)
		}
	}
	if blobExists(t, d["shared1"]) {
		t.Fatal("shared blob remains after concurrent deletion of both owners")
	}
	if !blobExists(t, d["exclusive"]) || !blobExists(t, d["configC"]) {
		t.Fatal("model-c data lost during concurrent deletion")
	}
}

func deleteAndReclaim(name string) error {
	if _, err := RemoveNamed(model.ParseName(name)); err != nil {
		return err
	}
	_, err = Reclaim(AuditOptions{Now: time.Now})
	return err
}

func TestInFlightBlobsAreNeverReclaimed(t *testing.T) {
	t.Setenv("OLLAMA_MODELS", t.TempDir())
	d := buildThreeModelStore(t)

	claim, err := BeginBlobWrite(d["exclusive"])
	if err != nil {
		t.Fatal(err)
	}

	// Even with no manifest referencing it, an in-use blob is retained.
	if _, err := RemoveNamed(model.ParseName("model-c")); err != nil {
		t.Fatal(err)
	}
	r, err := Reclaim(AuditOptions{Now: time.Now})
	if err != nil {
		t.Fatal(err)
	}
	if contains(r.RemovedBlobs, d["exclusive"]) {
		t.Fatal("in-use blob was reclaimed")
	}
	if !contains(r.InUse, d["exclusive"]) {
		t.Fatalf("in-use digest not reported: %v", r.InUse)
	}
	if !blobExists(t, d["exclusive"]) {
		t.Fatal("in-use blob deleted")
	}

	// A second claimant is rejected while the first is active.
	if _, err := BeginBlobWrite(d["exclusive"]); err != ErrObjectInUse {
		t.Fatalf("second claim err = %v, want ErrObjectInUse", err)
	}

	claim.Release()

	// After release with no references, it is an orphan and gets reclaimed.
	r2, err := Reclaim(AuditOptions{Now: time.Now})
	if err != nil {
		t.Fatal(err)
	}
	if !contains(r2.RemovedBlobs, d["exclusive"]) {
		t.Fatalf("released orphan not reclaimed: %v", r2.RemovedBlobs)
	}
}

