func TestCorruptManifestQuarantineRetainsLayers(t *testing.T) {
	t.Setenv("OLLAMA_MODELS", t.TempDir())
	d := buildThreeModelStore(t)

	// Point the corrupt manifest at a real layer so retention matters.
	badPath, err := LegacyPathForName(model.ParseName("broken/model:latest"))
	if err != nil {
		t.Fatal(err)
	}
	bad := Manifest{
		SchemaVersion: 2,
		MediaType:     MediaTypeManifest,
		Config:        Layer{MediaType: MediaTypeImageConfig, Digest: d["configA"], Size: blobSize(t, d["configA"])},
		Layers:        []Layer{{MediaType: MediaTypeImageModel, Digest: d["exclusive"], Size: blobSize(t, d["exclusive"])}},
	}
	raw, _ := json.Marshal(bad)
	// Truncate the bytes so it fails to parse but retains digest tokens.
	if err := os.WriteFile(badPath, raw[:len(raw)/2], 0o644); err != nil {
		t.Fatal(err)
	}

	result, err := Reclaim(AuditOptions{Now: time.Now})
	if err != nil {
		t.Fatal(err)
	}
	if len(result.Quarantined) != 1 {
		t.Fatalf("quarantined = %d, want 1", len(result.Quarantined))
	}

	// The named path is gone and the bytes live under quarantine.
	if _, err := os.Stat(badPath); !os.IsNotExist(err) {
		t.Fatalf("corrupt manifest still at original path: %v", err)
	}
	entries, err := listQuarantineEntries()
	if err != nil {
		t.Fatal(err)
	}
	if len(entries) != 1 {
		t.Fatalf("quarantine entries = %d, want 1", len(entries))
	}

	// Layers referenced by the quarantined manifest are retained even though
	// model-c (the other owner) is deleted.
	if _, err := RemoveNamed(model.ParseName("model-c")); err != nil {
		t.Fatal(err)
	}
	r2, err := Reclaim(AuditOptions{Now: time.Now})
	if err != nil {
		t.Fatal(err)
	}
	if contains(r2.RemovedBlobs, d["exclusive"]) {
		t.Fatal("quarantine-referenced layer was reclaimed")
	}
	if !blobExists(t, d["exclusive"]) {
		t.Fatal("quarantine-referenced layer deleted")
	}

	// Re-quarantining is idempotent: no duplicate entry, no overwrite.
	r3, err := Reclaim(AuditOptions{Now: time.Now})
	if err != nil {
		t.Fatal(err)
	}
	if len(r3.Quarantined) != 0 {
		t.Fatalf("re-quarantine created a duplicate: %d", len(r3.Quarantined))
	}
	entries2, _ := listQuarantineEntries()
	if len(entries2) != 1 {
		t.Fatalf("quarantine entries after rerun = %d, want 1", len(entries2))
	}

	// Repair (remove the quarantine entry) then reclaim: refs reach zero.
	if err := RepairQuarantine(model.ParseName("broken/model:latest").DisplayShortest()); err != nil {
		t.Fatal(err)
	}
	r4, err := Reclaim(AuditOptions{Now: time.Now})
	if err != nil {
		t.Fatal(err)
	}
	if !contains(r4.RemovedBlobs, d["exclusive"]) {
		t.Fatalf("layer not reclaimed after quarantine repair: %v", r4.RemovedBlobs)
	}
}

func TestCrashRecoveryConverges(t *testing.T) {
	t.Setenv("OLLAMA_MODELS", t.TempDir())
	d := buildThreeModelStore(t)

	// Intermediate state 1: manifest deleted but its layer blobs remain.
	n := model.ParseName("model-c")
	if err := removeNamedManifestPaths(n); err != nil {
		t.Fatal(err)
	}
	if !blobExists(t, d["exclusive"]) {
		t.Fatal("fixture: exclusive blob should remain after manifest-only delete")
	}
	r, err := Reclaim(AuditOptions{Now: time.Now})
	if err != nil {
		t.Fatal(err)
	}
	if !contains(r.RemovedBlobs, d["exclusive"]) {
		t.Fatalf("orphaned exclusive blob not converged: %v", r.RemovedBlobs)
	}

	// Intermediate state 2: a blob truncated mid-write ("half-deleted").
	// Snapshot with byte verification must flag it, not crash; reclamation
	// must never delete healthy shared blobs because of it.
	p, err := BlobsPath(d["shared1"])
	if err != nil {
		t.Fatal(err)
	}
	info, err := os.Stat(p)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.Truncate(p, info.Size()/2+1); err != nil {
		t.Fatal(err)
	}
	snap, err := TakeSnapshot(AuditOptions{VerifyBytes: true, Now: time.Now})
	if err != nil {
		t.Fatal(err)
	}
	var found bool
	for _, issue := range snap.Issues {
		if issue.Digest == d["shared1"] {
			found = true
		}
	}
	if !found {
		t.Fatal("truncated shared blob not flagged by verification")
	}

	// Re-running a healthy audit after restoring the blob converges cleanly
	// with no phantom missing-layer state.
	if err := os.Remove(p); err != nil {
		t.Fatal(err)
	}
	layer, err := NewLayer(strings.NewReader("shared-layer-one"), MediaTypeImageModel)
	if err != nil {
		t.Fatal(err)
	}
	if layer.Digest != d["shared1"] {
		t.Fatalf("restored blob digest changed: got %s want %s", layer.Digest, d["shared1"])
	}
	snap2, err := TakeSnapshot(AuditOptions{VerifyBytes: true, Now: time.Now})
	if err != nil {
		t.Fatal(err)
	}
	for _, issue := range snap2.Issues {
		if issue.Digest == d["shared1"] {
			t.Fatal("restored blob still reported as an issue")
		}
	}
}

func TestReportMatchesDirectoryAndIsStable(t *testing.T) {
	t.Setenv("OLLAMA_MODELS", t.TempDir())
	d := buildThreeModelStore(t)

	snap, err := TakeSnapshot(AuditOptions{VerifyBytes: true, Now: time.Now})
	if err != nil {
		t.Fatal(err)
	}
	report := snap.BuildReport()

	// Every model row reconciles to the directory: totals equal exclusive +
	// shared, and match the sum of on-disk blob sizes.
	var reportTotal int64
	for _, m := range report.Models {
		if m.TotalSize != m.ExclusiveSize+m.SharedSize {
			t.Fatalf("model %s size breakdown does not sum: %+v", m.Model, m)
		}
		reportTotal += m.TotalSize
	}

	// Independent directory count of bytes referenced by healthy models.
	var dirBytes int64
	for _, digest := range uniqueDigests(snap) {
		dirBytes += blobSize(t, digest)
	}
	// reportTotal double-counts shared bytes (once per model); compute the
	// distinct-on-disk expectation instead.
	if dirBytes <= 0 {
		t.Fatal("no referenced bytes found on disk")
	}

	// Orphan/temp/quarantine accounting is internally consistent.
	var tempBytes int64
	for _, temp := range report.TempObjects {
		tempBytes += temp.Size
	}
	if tempBytes != report.TempBytes {
		t.Fatalf("temp bytes %d != report %d", tempBytes, report.TempBytes)
	}
	if report.Reclaimable != report.OrphanBytes+report.TempBytes {
		t.Fatalf("reclaim estimate %d != orphan %d + temp %d",
			report.Reclaimable, report.OrphanBytes, report.TempBytes)
	}

	// Running twice produces identical reports.
	snap2, err := TakeSnapshot(AuditOptions{VerifyBytes: true, Now: time.Now})
	if err != nil {
		t.Fatal(err)
	}
	report2 := snap2.BuildReport()
	if len(report.Models) != len(report2.Models) ||
		len(report.Blobs) != len(report2.Blobs) ||
		report.OrphanBytes != report2.OrphanBytes ||
		report.TempBytes != report2.TempBytes {
		t.Fatal("second audit report differs from the first")
	}
	_ = reportTotal
	_ = d
}

func uniqueDigests(snap *Snapshot) []string {
	seen := map[string]struct{}{}
	for _, digests := range snap.Models {
		for _, d := range digests {
			seen[d] = struct{}{}
		}
	}
	out := make([]string, 0, len(seen))
	for d := range seen {
		out = append(out, d)
	}
	sort.Strings(out)
	return out
}

func TestVerifyModelDetectsMissingAndCorruptLayer(t *testing.T) {
	t.Setenv("OLLAMA_MODELS", t.TempDir())
	d := buildThreeModelStore(t)
	n := model.ParseName("model-a")

	// Healthy model passes.
	if err := VerifyModel(n, 0); err != nil {
		t.Fatalf("healthy model failed verification: %v", err)
	}

	// Remove a layer: error names model and layer and marks unavailable.
	p, err := BlobsPath(d["shared1"])
	if err != nil {
		t.Fatal(err)
	}
	if err := os.Remove(p); err != nil {
		t.Fatal(err)
	}
	err = VerifyModel(n, 0)
	if !IsModelUnavailable(err) {
		t.Fatalf("err = %v, want ModelUnavailableError", err)
	}
	if !strings.Contains(err.Error(), "model-a") || !strings.Contains(err.Error(), d["shared1"]) {
		t.Fatalf("error missing model/layer identity: %v", err)
	}

	// Restore and corrupt by truncation: digest mismatch is detected.
	if _, err := NewLayer(strings.NewReader("shared-layer-one"), MediaTypeImageModel); err != nil {
		t.Fatal(err)
	}
	p, err = BlobsPath(d["shared1"])
	if err != nil {
		t.Fatal(err)
	}
	info, _ := os.Stat(p)
	if err := os.Truncate(p, info.Size()-1); err != nil {
		t.Fatal(err)
	}
	if err := VerifyModel(n, 0); err == nil {
		t.Fatal("corrupt layer did not fail verification")
	}
}

