// VerifyModel checks every config and layer blob a named model needs before
// it is loaded or served. A missing or non-matching blob produces an error
// naming the model and the specific layer and marks the model unavailable.
// Verification is streamed with bounded memory.
func VerifyModel(n model.Name, chunkSize int) error {
	if chunkSize <= 0 {
		chunkSize = DefaultAuditChunkSize
	}

	data, err := ReadManifestData(n)
	if err != nil {
		return &ModelUnavailableError{Model: n.DisplayShortest(), Reason: fmt.Sprintf("manifest unreadable: %v", err)}
	}

	var m Manifest
	if err := json.Unmarshal(data, &m); err != nil {
		return &ModelUnavailableError{Model: n.DisplayShortest(), Reason: fmt.Sprintf("manifest unparseable: %v", err)}
	}

	layers := append([]Layer{}, m.Layers...)
	if m.Config.Digest != "" {
		layers = append(layers, m.Config)
	}

	seen := make(map[string]struct{})
	for _, layer := range layers {
		if layer.Digest == "" {
			continue
		}
		digest := NormalizeDigest(layer.Digest)
		if _, dup := seen[digest]; dup {
			continue
		}
		seen[digest] = struct{}{}

		path, err := BlobsPath(digest)
		if err != nil {
			return &ModelUnavailableError{Model: n.DisplayShortest(), Layer: digest, Reason: err.Error()}
		}
		info, err := os.Stat(path)
		if err != nil {
			return &ModelUnavailableError{
				Model: n.DisplayShortest(), Layer: digest,
				Reason: "layer missing from store",
			}
		}
		if layer.Size > 0 && info.Size() != layer.Size {
			return &ModelUnavailableError{
				Model: n.DisplayShortest(), Layer: digest,
				Reason: fmt.Sprintf("size mismatch: on disk %d, declared %d", info.Size(), layer.Size),
			}
		}
		if err := checkBlobDigestChunked(path, digest, chunkSize); err != nil {
			return &ModelUnavailableError{
				Model: n.DisplayShortest(), Layer: digest,
				Reason: err.Error(),
			}
		}
	}
	return nil
}

// ModelUnavailableError names both the model and the layer that failed
// pre-use verification, so callers never surface a generic load failure.
type ModelUnavailableError struct {
	Model  string `json:"model"`
	Layer  string `json:"layer,omitempty"`
	Reason string `json:"reason"`
}

func (e *ModelUnavailableError) Error() string {
	if e.Layer == "" {
		return fmt.Sprintf("model %s unavailable: %s", e.Model, e.Reason)
	}
	return fmt.Sprintf("model %s unavailable: layer %s: %s", e.Model, e.Layer, e.Reason)
}

// IsModelUnavailable reports whether err marks a model as not servable.
func IsModelUnavailable(err error) bool {
	var target *ModelUnavailableError
	return errors.As(err, &target)
}

func checkBlobDigestChunked(path, digest string, chunkSize int) error {
	f, err := os.Open(path)
	if err != nil {
		return err
	}
	defer f.Close()
	return checkBlobDigestReaderBuffered(f, digest, chunkSize)
}

// RepairQuarantine removes a quarantine entry after its model has been either
// re-pulled (a healthy named manifest now references the same digests) or
// explicitly deleted. Subsequent Reclaim calls collect any digests whose
// reference count has reached zero.
func RepairQuarantine(modelName string) error {
	entries, err := listQuarantineEntries()
	if err != nil {
		return err
	}
	for _, entry := range entries {
		if entry.Model.DisplayShortest() == modelName || entry.Model.String() == modelName {
			return removeQuarantineEntry(entry)
		}
	}
	return os.ErrNotExist
}
