		return nil, time.Time{}, false, err
	}

	var parent manifest.Manifest
	if err := json.Unmarshal(data, &parent); err != nil {
		return nil, time.Time{}, false, err
	}
	if parent.MediaType != manifest.MediaTypeManifestList {
		return nil, time.Time{}, false, nil
	}
