// TestUnavailableModelReportsModelAndLayer builds a model through the normal
// create path, corrupts one of its weight blobs, and asserts that the serving
// metadata path rejects it with an error naming both the model and the layer.
func TestUnavailableModelReportsModelAndLayer(t *testing.T) {
	gin.SetMode(gin.TestMode)
	t.Setenv("OLLAMA_MODELS", t.TempDir())

	var s Server
	_, digest := createBinFile(t, nil, nil)
	w := createRequest(t, s.CreateHandler, api.CreateRequest{
		Name:  "unavailable-test",
		Files: map[string]string{"test.gguf": digest},
	})
	if w.Code != 200 {
		t.Fatalf("create status = %d, want 200", w.Code)
	}

	// Healthy model passes both the cheap metadata gate and the full check.
	if _, err := GetModel("unavailable-test"); err != nil {
		t.Fatalf("healthy model unavailable: %v", err)
	}

	// Locate the model's weight layer from its manifest, then truncate it.
	mf, err := manifest.ParseNamedManifest(mustParseName(t, "unavailable-test"))
	if err != nil {
		t.Fatal(err)
	}
	if len(mf.Layers) == 0 {
		t.Fatal("manifest has no layers to corrupt")
	}
	target := mf.Layers[0].Digest
	blobPath, err := manifest.BlobsPath(target)
	if err != nil {
		t.Fatal(err)
	}
	info, err := os.Stat(blobPath)
	if err != nil {
		t.Fatal(err)
	}
	if info.Size() <= 1 {
		t.Fatalf("test blob too small to truncate: %d", info.Size())
	}
	if err := os.Truncate(blobPath, info.Size()-1); err != nil {
		t.Fatal(err)
	}

	// The metadata gate must fail with model and layer identity.
	_, err = GetModel("unavailable-test")
	if !manifest.IsModelUnavailable(err) {
		t.Fatalf("err = %v, want ModelUnavailableError", err)
	}
	if !strings.Contains(err.Error(), "unavailable-test") {
		t.Fatalf("error does not name the model: %v", err)
	}
	if !strings.Contains(err.Error(), target) {
		t.Fatalf("error does not name the layer: %v", err)
	}
}

// TestReclaimSurvivesCorruptManifestAndKeepsOthersWorking is the server-level
