func TestReclaimSurvivesCorruptManifestAndKeepsOthersWorking(t *testing.T) {
	gin.SetMode(gin.TestMode)
	root := t.TempDir()
	t.Setenv("OLLAMA_MODELS", root)

	var s Server
	_, digest := createBinFile(t, nil, nil)
	for _, name := range []string{"left", "right"} {
		if w := createRequest(t, s.CreateHandler, api.CreateRequest{
			Name:  name,
			Files: map[string]string{"test.gguf": digest},
		}); w.Code != 200 {
			t.Fatalf("create %s status = %d", name, w.Code)
		}
	}

	// Write an unparseable manifest at a valid legacy named path.
	badName := mustParseName(t, "broken/model")
	badPath, err := manifest.LegacyPathForName(badName)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.MkdirAll(filepath.Dir(badPath), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(badPath, []byte("{corrupt"), 0o644); err != nil {
		t.Fatal(err)
	}

	result, err := manifest.Reclaim(manifest.AuditOptions{})
	if err != nil {
		t.Fatalf("reclaim failed: %v", err)
	}
	if len(result.Quarantined) != 1 {
		t.Fatalf("quarantined = %d, want 1", len(result.Quarantined))
	}

	// Healthy models remain servable.
	for _, name := range []string{"left", "right"} {
		if _, err := GetModel(name); err != nil {
			t.Fatalf("model %s must remain available after quarantine: %v", name, err)
		}
	}

	// The shared weight blob survives because both healthy models reference it.
	mf, err := manifest.ParseNamedManifest(mustParseName(t, "left"))
	if err != nil {
		t.Fatal(err)
	}
	shared := mf.Layers[0].Digest
	p, err := manifest.BlobsPath(shared)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := os.Stat(p); err != nil {
		t.Fatalf("shared blob lost after quarantine: %v", err)
	}

	// A second pass is stable: no new quarantine action, no blob loss.
	again, err := manifest.Reclaim(manifest.AuditOptions{})
	if err != nil {
		t.Fatalf("second reclaim failed: %v", err)
	}
	if len(again.Quarantined) != 0 {
		t.Fatalf("re-quarantine created a duplicate: %d", len(again.Quarantined))
	}
}
