// digestTokenPattern matches a content-addressed blob token in either the
// manifest spelling (sha256-<hex>) or the canonical digest spelling.
var digestTokenPattern = regexp.MustCompile(`sha256[:-][0-9a-fA-F]{64}`)

// DefaultAuditChunkSize bounds the memory used while hashing any single blob:
// layers are streamed through a fixed buffer, never read whole.
const DefaultAuditChunkSize = 4 * 1024 * 1024

// AuditOptions controls a store snapshot and audit.
type AuditOptions struct {
	// VerifyBytes streams every referenced blob and checks its sha256 and
	// declared size. When false, only presence and on-disk size are checked.
	VerifyBytes bool
	// ChunkSize bounds per-blob read buffering. Zero selects
	// DefaultAuditChunkSize.
	ChunkSize int
	// MaxBlobBytes, when positive, skips byte verification above this total
	// across the run (the remaining blobs are marked skipped, not failed).
	MaxBlobBytes int64
	// Now supplies the clock for temp-file age decisions.
	Now func() time.Time
	// MinTempAge is how old an unlocked staging file must be before it is
	// considered abandoned.
	MinTempAge time.Duration
}

// LayerIssue identifies a problem found on one layer of one model.
type LayerIssue struct {
	Model  model.Name `json:"model"`
	Digest string     `json:"digest"`
	Size   int64      `json:"size"`
	Reason string     `json:"reason"`
}

// BlobRef is one blob's row in the reference-count snapshot.
type BlobRef struct {
	Digest       string   `json:"digest"`
	Size         int64    `json:"size"`
	References   int      `json:"references"`
	ReferencedBy []string `json:"referencedBy"` // model display names + quarantine origins
	// Shared is true when more than one model references the blob.
	Shared bool `json:"shared"`
	// ExclToModel names the single referencing model when not shared.
	ExclToModel string `json:"exclToModel,omitempty"`
	State       string `json:"state"` // ok, missing, size-mismatch, digest-mismatch, changed-during-audit, skipped, unreferenced
}

// TempObject is a partial or staging file observed in the blobs directory.
type TempObject struct {
	Path        string `json:"path"`
	Digest      string `json:"digest,omitempty"`
	Size        int64  `json:"size"`
	InUse       bool   `json:"inUse"`
	Reclaimable bool   `json:"reclaimable"`
	Reason      string `json:"reason,omitempty"`
}

// Snapshot is one consistent view of the whole store. Reference counting,
// verification, reclamation and reporting are all derived from this single
// structure, so they can never disagree.
type Snapshot struct {
	// Models maps logical model name to the digests reachable from it.
	Models map[model.Name][]string
	// ModelBlobs holds the manifest-recorded layer size per (model, digest).
	ModelBlobs map[model.Name]map[string]int64
	// Refs is the per-blob reference accounting, keyed by canonical digest.
	Refs map[string]*BlobRef
	// Quarantine holds manifests moved aside during this or an earlier audit.
	Quarantine []*QuarantineEntry
	// QuarantineRefs retains every digest referenced by quarantine entries.
	QuarantineRefs map[string]struct{}
	// Orphans are content-addressed blobs no manifest references.
	Orphans []string
	// Temps are partial/staging files and their liveness classification.
	Temps []TempObject
	// Issues lists every per-layer integrity problem found.
	Issues []LayerIssue
	// ManifestIssues lists manifests that failed to parse or verify (and were
	// quarantined when the audit was asked to quarantine).
	ManifestIssues []LayerIssue
	// Inaccessible lists paths that could not be read; the audit is marked
	// incomplete rather than deleting anything based on them.
	Inaccessible []string
	// ReclaimableBytes estimates bytes safely removable right now.
	ReclaimableBytes int64
	// OrphanBytes / TempBytes break the reclaim estimate down.
	OrphanBytes int64
	TempBytes   int64
	// Incomplete is true when an unreadable directory made the snapshot
	// partial. Reclamation is refused while this is set.
	Incomplete bool
	// VerifiedBytes is the total streamed through sha256 in this audit.
	VerifiedBytes int64
}

// ModelReport is one model's row in the report.
type ModelReport struct {
	Model         model.Name `json:"model"`
	ExclusiveSize int64      `json:"exclusiveBytes"`
	SharedSize    int64      `json:"sharedBytes"`
	TotalSize     int64      `json:"totalBytes"`
	Layers        int        `json:"layers"`
	Available     bool       `json:"available"`
}

// Report is the serializable audit output. Only model names, digests, sizes
// and reasons are ever present — no layer contents or prompts.
type Report struct {
	GeneratedAt   time.Time         `json:"generatedAt"`
	Incomplete    bool              `json:"incomplete"`
	Models        []ModelReport     `json:"models"`
	Blobs         []BlobRef         `json:"blobs"`
	Orphans       []string          `json:"orphans"`
	OrphanBytes   int64             `json:"orphanBytes"`
	TempObjects   []TempObject      `json:"tempObjects"`
	TempBytes     int64             `json:"tempBytes"`
	Quarantine    []QuarantineEntry `json:"quarantine"`
	Issues        []LayerIssue      `json:"issues"`
	Inaccessible  []string          `json:"inaccessible"`
	Reclaimable   int64             `json:"reclaimableBytes"`
	VerifiedBytes int64             `json:"verifiedBytes"`
}

// TakeSnapshot walks the store once and builds the single Snapshot used by
// verification, reclamation and reporting. The store mutex is held for the
// filesystem walk so a concurrent delete or manifest write cannot make the
// reference set and the blob set diverge; byte verification happens after the
// walk without holding the mutex and tolerates concurrent change.
func TakeSnapshot(opts AuditOptions) (*Snapshot, error) {
	opts = auditDefaults(opts)

	manifestStoreMu.Lock()
	snap, err := takeSnapshotLocked(opts)
	manifestStoreMu.Unlock()
	if err != nil {
		return nil, err
	}

	if opts.VerifyBytes {
		verifySnapshotBlobs(snap, opts)
	}

	computeReclaimEstimate(snap, opts)
	return snap, nil
}

// auditDefaults fills the optional fields of opts so every entry point
// (TakeSnapshot, Reclaim, AuditAndQuarantine) behaves the same.
func auditDefaults(opts AuditOptions) AuditOptions {
	if opts.ChunkSize <= 0 {
		opts.ChunkSize = DefaultAuditChunkSize
	}
	if opts.Now == nil {
		opts.Now = time.Now
	}
	if opts.MinTempAge <= 0 {
		opts.MinTempAge = layerPruneMinTempAge()
	}
	return opts
}

func takeSnapshotLocked(opts AuditOptions) (*Snapshot, error) {
	opts = auditDefaults(opts)
	snap := &Snapshot{
		Models:         make(map[model.Name][]string),
		ModelBlobs:     make(map[model.Name]map[string]int64),
		Refs:           make(map[string]*BlobRef),
		QuarantineRefs: make(map[string]struct{}),
	}

	// Existing quarantine entries still protect their references. Build a
	// set of the on-disk manifest paths that were already moved aside, so a
	// re-audit neither re-quarantines nor double-counts them.
	entries, err := listQuarantineEntries()
	if err != nil {
		return nil, err
	}
	snap.Quarantine = entries
	quarantinedPaths := make(map[string]struct{})
	for _, entry := range entries {
		for _, d := range entry.References {
			snap.QuarantineRefs[NormalizeDigest(d)] = struct{}{}
		}
		quarantinedPaths[filepath.FromSlash(entry.Path)] = struct{}{}
	}

	// One reference map from every named manifest in both trees. A
	// not-exist error here means an entry vanished between the glob and its
	// lstat during a concurrent delete; that is benign convergence, not an
	// unreadable store, so it does not mark the snapshot incomplete.
	refs, err := namedManifestRefs(true)
	if err != nil && !os.IsNotExist(err) {
		snap.Incomplete = true
		snap.Inaccessible = append(snap.Inaccessible, err.Error())
	}

	// Deterministic order makes reports and quarantine decisions stable.
	names := make([]model.Name, 0, len(refs))
	for n := range refs {
		names = append(names, n)
	}
	sort.Slice(names, func(i, j int) bool { return names[i].String() < names[j].String() })

	for _, n := range names {
		ref := refs[n]
		if rel, relErr := filepath.Rel(ref.root, ref.path); relErr == nil {
			if _, already := quarantinedPaths[rel]; already {
				// Moved aside in an earlier audit; its references are already
				// retained and it must not be re-quarantined or counted again.
				continue
			}
		}
		data, _, digest, readErr := readVerifiedManifestLocked(ref.path, ref.root)
		if readErr != nil {
			// A manifest removed between the directory read and this read is
			// an ordinary concurrent delete, not corruption: skip it and let
			// the next audit converge. It must never mark the store incomplete.
			if os.IsNotExist(readErr) {
				continue
			}
			// Salvage whatever digests the bytes still contain so their
			// layers are retained, then record the issue. Quarantine is the
			// caller's explicit choice (AuditAndQuarantine); here we only
			// mark the manifest.
			raw, fileErr := os.ReadFile(ref.path)
			if fileErr != nil && os.IsNotExist(fileErr) {
				continue
			}
			var salvaged []string
			if fileErr == nil {
				salvaged = salvageDigests(raw)
			}
			snap.ManifestIssues = append(snap.ManifestIssues, LayerIssue{
				Model:  n,
				Digest: digest,
				Reason: fmt.Sprintf("unreadable manifest: %v", readErr),
			})
			for _, d := range salvaged {
				snap.QuarantineRefs[d] = struct{}{}
			}
			slog.Warn("bad manifest", "name", n, "error", readErr)
			continue
		}

		digests, sizes, refErr := referencedBlobsWithSizes(digest, data)
		if refErr != nil {
			snap.ManifestIssues = append(snap.ManifestIssues, LayerIssue{
				Model:  n,
				Digest: digest,
				Reason: fmt.Sprintf("unparseable manifest: %v", refErr),
			})
			for _, d := range salvageDigests(data) {
				snap.QuarantineRefs[d] = struct{}{}
			}
			slog.Warn("bad manifest", "name", n, "error", refErr)
			continue
		}

		snap.Models[n] = digests
		snap.ModelBlobs[n] = sizes
		for _, d := range digests {
			ref := snap.Refs[d]
			if ref == nil {
				ref = &BlobRef{Digest: d, Size: sizes[d]}
				snap.Refs[d] = ref
			}
			ref.References++
			ref.ReferencedBy = append(ref.ReferencedBy, n.DisplayShortest())
		}
	}

	// Classify everything physically present in the blobs directory.
	if err := classifyBlobDirectory(snap, opts); err != nil {
		snap.Incomplete = true
		snap.Inaccessible = append(snap.Inaccessible, err.Error())
		// Keep any quarantine references already discovered so the store
		// stays conservative, but never reclaim from a partial directory view.
	}

	// Finalize shared/exclusive accounting.
	for _, ref := range snap.Refs {
		sort.Strings(ref.ReferencedBy)
		ref.Shared = ref.References > 1
		if !ref.Shared && len(ref.ReferencedBy) > 0 {
			ref.ExclToModel = ref.ReferencedBy[0]
		}
		switch ref.State {
		case "":
			ref.State = "ok"
		}
	}

	return snap, nil
}

// referencedBlobsWithSizes returns the canonical digests reachable from a
// manifest object and the size each declares. Manifest-list children, digest
// references and legacy/downgrade anchors all flow through the same logic, so
// a layer referenced more than once by one model is counted a single time.
func referencedBlobsWithSizes(manifestDigest string, data []byte) ([]string, map[string]int64, error) {
	seen := make(map[string]int64)

	addLayer := func(l Layer) {
		if l.Digest == "" {
			return
		}
		d := NormalizeDigest(l.Digest)
		if ValidateDigest(d) != nil {
			return
		}
		if _, ok := seen[d]; !ok {
			seen[d] = l.Size
		}
	}

	var m Manifest
	if err := parseManifestInto(data, &m); err != nil {
		return nil, nil, err
	}

	addManifestDigest := func(d string) {
		if d == "" {
			return
		}
		nd := NormalizeDigest(d)
		if ValidateDigest(nd) == nil {
			if _, ok := seen[nd]; !ok {
				seen[nd] = 0
			}
		}
	}
	addManifestDigest(manifestDigest)

	if m.MediaType == MediaTypeManifestList {
		for i := range m.Manifests {
			child := &m.Manifests[i]
			if child.isReference() {
				childDigest := child.BlobDigest()
				addManifestDigest(childDigest)
				resolved, ok, err := parseManifestBlobIfExists(childDigest)
				if err != nil {
					return nil, nil, err
				}
				if !ok {
					continue
				}
				child = resolved
			} else {
				addManifestDigest(child.BlobDigest())
			}
			for _, layer := range append(child.Layers, child.Config) {
				addLayer(layer)
			}
		}
	} else {
		for _, layer := range append(m.Layers, m.Config) {
			addLayer(layer)
		}
	}

	digests := make([]string, 0, len(seen))
	for d := range seen {
		digests = append(digests, d)
	}
	sort.Strings(digests)
	return digests, seen, nil
}

func parseManifestInto(data []byte, m *Manifest) error {
	return jsonUnmarshalManifest(data, m)
}

// classifyBlobDirectory splits the blobs directory into referenced blobs,
// orphans and liveness-classified staging files, all from the same readdir.
func classifyBlobDirectory(snap *Snapshot, opts AuditOptions) error {
	blobs, err := BlobsPath("")
	if err != nil {
		return err
	}
	entries, err := os.ReadDir(blobs)
	if err != nil {
		return fmt.Errorf("read blobs directory: %w", err)
	}

	now := opts.Now()
	for _, entry := range entries {
		if entry.IsDir() {
			continue
		}
		name := entry.Name()
		info, err := entry.Info()
		if err != nil {
			snap.Inaccessible = append(snap.Inaccessible, filepath.Join(blobs, name))
			continue
		}

		if digest, ok := classifyTempEntry(name); ok {
			inUse := isWriteActive(digest)
			temp := TempObject{
				Path:   filepath.Join(blobs, name),
				Digest: digest,
				Size:   info.Size(),
				InUse:  inUse,
			}
			switch {
			case inUse:
				temp.Reason = "active write in progress"
			case now.Sub(info.ModTime()) < opts.MinTempAge:
				temp.Reason = "recent staging file; within grace period"
			default:
				temp.Reclaimable = true
				temp.Reason = "abandoned staging file with no active claim"
				snap.TempBytes += info.Size()
			}
			snap.Temps = append(snap.Temps, temp)
			continue
		}

		if !blobFilenamePattern.MatchString(name) {
			// Unrecognized non-blob file: never delete what we cannot name.
			snap.Temps = append(snap.Temps, TempObject{
				Path:   filepath.Join(blobs, name),
				InUse:  false,
				Reason: "unrecognized file; retained",
			})
			continue
		}

		digest := "sha256:" + strings.TrimPrefix(name, "sha256-")
		ref, referenced := snap.Refs[digest]
		_, quarantined := snap.QuarantineRefs[digest]
		if !referenced && !quarantined {
			snap.Orphans = append(snap.Orphans, digest)
			snap.OrphanBytes += info.Size()
			if r := snap.Refs[digest]; r == nil {
				snap.Refs[digest] = &BlobRef{Digest: digest, Size: info.Size(), State: "unreferenced"}
			}
			continue
		}

		if ref == nil {
			// Referenced only by a quarantined manifest.
			ref = &BlobRef{Digest: digest, State: "ok"}
			snap.Refs[digest] = ref
		}
		if ref.Size == 0 {
			ref.Size = info.Size()
		}

		// Presence + declared-size check. Byte hashing is a separate pass.
		if info.Size() != ref.Size && ref.Size != 0 {
			ref.State = "size-mismatch"
			snap.Issues = append(snap.Issues, LayerIssue{
				Digest: digest,
				Size:   info.Size(),
				Reason: fmt.Sprintf("size mismatch: on disk %d, declared %d", info.Size(), ref.Size),
			})
		}
	}
	return nil
}

// verifySnapshotBlobs streams every referenced, present blob through sha256
// with a bounded buffer. A blob replaced or removed mid-audit is marked and
// never treated as a failure that authorizes deletion.
func verifySnapshotBlobs(snap *Snapshot, opts AuditOptions) {
	digests := make([]string, 0, len(snap.Refs))
	for d := range snap.Refs {
		digests = append(digests, d)
	}
	sort.Strings(digests)

	var budget int64 = opts.MaxBlobBytes
	for _, digest := range digests {
		ref := snap.Refs[digest]
		if ref.State == "unreferenced" {
			continue
		}
		if budget > 0 && snap.VerifiedBytes >= budget {
			if ref.State == "ok" {
				ref.State = "skipped"
			}
			continue
		}
		issue, n := verifyOneBlob(digest, ref, opts.ChunkSize)
		snap.VerifiedBytes += n
		if issue != nil {
			ref.State = issueState(issue.Reason)
			snap.Issues = append(snap.Issues, *issue)
		}
	}
}

func issueState(reason string) string {
	switch {
	case strings.Contains(reason, "changed during audit"):
		return "changed-during-audit"
	case strings.Contains(reason, "missing"):
		return "missing"
	case strings.Contains(reason, "size mismatch"):
		return "size-mismatch"
	default:
		return "digest-mismatch"
	}
}

// verifyOneBlob hashes one blob without ever reading it fully into memory.
func verifyOneBlob(digest string, ref *BlobRef, chunkSize int) (*LayerIssue, int64) {
	path, err := BlobsPath(digest)
	if err != nil {
		return &LayerIssue{Digest: digest, Reason: fmt.Sprintf("path error: %v", err)}, 0
	}

	before, err := os.Stat(path)
	if err != nil {
		if os.IsNotExist(err) {
			return &LayerIssue{Digest: digest, Reason: "missing blob"}, 0
		}
		return &LayerIssue{Digest: digest, Reason: fmt.Sprintf("stat error: %v", err)}, 0
	}

	f, err := os.Open(path)
	if err != nil {
		return &LayerIssue{Digest: digest, Reason: fmt.Sprintf("open error: %v", err)}, 0
	}
	defer f.Close()

	h := sha256.New()
	n, err := io.CopyBuffer(h, f, make([]byte, chunkSize))
	if err != nil {
		return &LayerIssue{Digest: digest, Size: n, Reason: fmt.Sprintf("read error: %v", err)}, n
	}

	after, err := os.Stat(path)
	if err != nil {
		return &LayerIssue{Digest: digest, Reason: "changed during audit: removed while hashing"}, n
	}
	if before.ModTime() != after.ModTime() || before.Size() != after.Size() {
		return &LayerIssue{Digest: digest, Reason: "changed during audit: replaced while hashing"}, n
	}

	got := fmt.Sprintf("sha256:%x", h.Sum(nil))
	if got != digest {
		return &LayerIssue{Digest: digest, Size: n, Reason: fmt.Sprintf("digest mismatch: want %s, got %s", digest, got)}, n
	}
	if ref.Size != 0 && n != ref.Size {
		return &LayerIssue{Digest: digest, Size: n, Reason: fmt.Sprintf("size mismatch: on disk %d, declared %d", n, ref.Size)}, n
	}
	return nil, n
}

func computeReclaimEstimate(snap *Snapshot, opts AuditOptions) {
	snap.ReclaimableBytes = snap.OrphanBytes + snap.TempBytes
}

// BuildReport turns a snapshot into the stable, serializable report. Every
// number is derived from the same Snapshot the reclaimer uses.
func (snap *Snapshot) BuildReport() *Report {
	r := &Report{
		GeneratedAt:   time.Now().UTC(),
		Incomplete:    snap.Incomplete,
		Orphans:       append([]string(nil), snap.Orphans...),
		OrphanBytes:   snap.OrphanBytes,
		TempObjects:   append([]TempObject(nil), snap.Temps...),
		TempBytes:     snap.TempBytes,
		Issues:        append([]LayerIssue(nil), snap.Issues...),
		Inaccessible:  append([]string(nil), snap.Inaccessible...),
		Reclaimable:   snap.ReclaimableBytes,
		VerifiedBytes: snap.VerifiedBytes,
	}

	for _, entry := range snap.Quarantine {
		r.Quarantine = append(r.Quarantine, *entry)
	}

	names := make([]model.Name, 0, len(snap.Models))
	for n := range snap.Models {
		names = append(names, n)
	}
	sort.Slice(names, func(i, j int) bool { return names[i].String() < names[j].String() })

	for _, n := range names {
		digests := snap.Models[n]
		row := ModelReport{Model: n, Layers: len(digests), Available: true}
		for _, d := range digests {
			ref := snap.Refs[d]
			size := snap.ModelBlobs[n][d]
			if size == 0 && ref != nil {
				size = ref.Size
			}
			row.TotalSize += size
			if ref != nil && ref.Shared {
				row.SharedSize += size
			} else {
				row.ExclusiveSize += size
			}
			if ref != nil && ref.State != "ok" && ref.State != "skipped" && ref.State != "" {
				row.Available = false
			}
		}
		r.Models = append(r.Models, row)
	}

	digests := make([]string, 0, len(snap.Refs))
	for d := range snap.Refs {
		digests = append(digests, d)
	}
	sort.Strings(digests)
	for _, d := range digests {
		r.Blobs = append(r.Blobs, *snap.Refs[d])
	}
	return r
}
