// fileLock is an advisory, process-scoped lock on a file. It combines an
// in-process mutex with a non-blocking flock so that concurrent writers inside
// this process and writers in other processes both serialize on the same
// on-disk object.
type fileLock struct {
	mu   sync.Mutex
	path string
	f    *os.File
	held bool
}

// locksDir returns the directory that holds in-flight lock files. It is created
// lazily so read-only stores never fail just from being asked for the path.
func locksDir() (string, error) {
	blobs, err := BlobsPath("")
	if err != nil {
		return "", err
	}
	return filepath.Join(filepath.Dir(blobs), "locks"), nil
}

// lockPathForDigest maps a blob digest to its lock file path. The mapping is
// purely lexical: no blob needs to exist for its lock to be taken, which is
// what protects partial and not-yet-renamed downloads.
func lockPathForDigest(digest string) (string, error) {
	normalized := NormalizeDigest(digest)
	if err := ValidateDigest(normalized); err != nil {
		return "", err
	}
	dir, err := locksDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(dir, strings.ReplaceAll(normalized, ":", "-")+".lock"), nil
}

// acquireFileLock opens (creating if needed) the lock file and takes an
// exclusive, non-blocking flock. EWOULDBLOCK means another holder is active.
// The in-process mutex keeps two goroutines in this process from sharing one
// underlying file description.
func acquireFileLock(path string) (*fileLock, error) {
	l := &fileLock{path: path}
	l.mu.Lock()

	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		l.mu.Unlock()
		return nil, err
	}

	f, err := os.OpenFile(path, os.O_CREATE|os.O_RDWR, 0o644)
	if err != nil {
		l.mu.Unlock()
		return nil, err
	}

	if err := unix.Flock(int(f.Fd()), unix.LOCK_EX|unix.LOCK_NB); err != nil {
		f.Close()
		l.mu.Unlock()
		if err == unix.EWOULDBLOCK {
			return nil, ErrObjectInUse
		}
		return nil, err
	}

	l.f = f
	l.held = true
	return l, nil
}

func (l *fileLock) release() {
	if !l.held {
		l.mu.Unlock()
		return
	}
	_ = unix.Flock(int(l.f.Fd()), unix.LOCK_UN)
	_ = l.f.Close()
	l.held = false
	// Stale lock files from crashed processes are harmless (flock state is
	// released by the kernel on close/exit); remove ours best-effort.
	_ = os.Remove(l.path)
	l.mu.Unlock()
}

// lockHeldByOtherProcess probes the lock file without blocking. A missing
// lock file or a flock we can take means no other process holds it.
func lockHeldByOtherProcess(digest string) bool {
	path, err := lockPathForDigest(digest)
	if err != nil {
		return false
	}
	f, err := os.OpenFile(path, os.O_RDWR, 0o644)
	if err != nil {
		return false
	}
	defer f.Close()
	if err := unix.Flock(int(f.Fd()), unix.LOCK_EX|unix.LOCK_NB); err != nil {
		return err == unix.EWOULDBLOCK
	}
	_ = unix.Flock(int(f.Fd()), unix.LOCK_UN)
	return false
}
