package manifest

import (
	"errors"
	"os"
	"path/filepath"
	"regexp"
	"sync"
)

// ErrObjectInUse reports that a blob is currently being downloaded or written
// and therefore cannot be audited for deletion or reclaimed.
var ErrObjectInUse = errors.New("blob is in use by an active download or write")

// Releaser releases an in-flight claim. It is safe to call once; further calls
// are no-ops.
type Releaser interface {
	Release()
}

type noopReleaser struct{}

func (noopReleaser) Release() {}

// inflightMu guards active, the set of digests claimed within this process.
// The on-disk flock (see inflight_{unix,windows}.go) extends the same claim
// across processes and survives nothing by design: the kernel releases it when
// a process exits, which is exactly what crash recovery needs.
var inflightMu sync.Mutex
var active = make(map[string]int)

// BeginBlobWrite marks digest as occupied for the duration of a download or
// blob write. It returns ErrObjectInUse if another holder (in this or another
// process) holds the claim. The returned Releaser must be invoked when the
// write finishes, succeeds or fails. Reads never take this lock.
func BeginBlobWrite(digest string) (Releaser, error) {
	lockPath, err := lockPathForDigest(digest)
	if err != nil {
		return nil, err
	}

	lock, err := acquireFileLock(lockPath)
	if err != nil {
		return nil, err
	}

	normalized := NormalizeDigest(digest)
	inflightMu.Lock()
	active[normalized]++
	inflightMu.Unlock()

	return &writeClaim{digest: normalized, lock: lock}, nil
}

type writeClaim struct {
	once   sync.Once
	digest string
	lock   *fileLock
}

func (c *writeClaim) Release() {
	c.once.Do(func() {
		inflightMu.Lock()
		if active[c.digest] > 0 {
			active[c.digest]--
			if active[c.digest] == 0 {
				delete(active, c.digest)
			}
		}
		inflightMu.Unlock()
		c.lock.release()
	})
}

// IsBlobInUse reports whether digest currently has an active write claim.
// In-process claims are answered without touching the filesystem; anything
// else requires a non-blocking flock probe (see lockHeldByOtherProcess).
func IsBlobInUse(digest string) bool {
	normalized := NormalizeDigest(digest)
	inflightMu.Lock()
	_, inProcess := active[normalized]
	inflightMu.Unlock()
	return inProcess || lockHeldByOtherProcess(normalized)
}

var (
	// sha256-<64 hex> with a download suffix: -partial, -partial-N or .tmp
	partialBlobPattern = regexp.MustCompile(`^(sha256-[0-9a-fA-F]{64})(?:-partial(?:-[0-9]+)?|\.tmp)$`)
	// temp files created while staging a blob or manifest (os.CreateTemp prefixes)
	tempFilePattern = regexp.MustCompile(`^(?:sha256-|\.manifest-)`)
)

// classifyTempEntry maps an entry in the blobs directory to the digest it is
// staging and whether it is a recognizable partial/temp object. ok is false
// for completed, content-addressed blobs and anything unrecognized.
//
// Recognized shapes:
//   - sha256-<hex>-partial, -partial-N, .tmp  (resumable download state)
//   - sha256-<random> / .manifest-<random>    (CreateTemp staging files)
func classifyTempEntry(name string) (digest string, ok bool) {
	if m := partialBlobPattern.FindStringSubmatch(name); m != nil {
		return NormalizeDigest(m[1]), true
	}
	if tempFilePattern.MatchString(name) && !blobFilenamePattern.MatchString(name) {
		// CreateTemp names embed no target digest. Callers decide liveness
		// from age and directory-wide claims; return the empty digest.
		return "", true
	}
	return "", false
}

// partialDigestForPath returns the normalized digest a partial/temp blob path
// is staging, or "" if the filename is not a recognized partial shape.
func partialDigestForPath(path string) string {
	digest, ok := classifyTempEntry(filepath.Base(path))
	if !ok {
		return ""
	}
	return digest
}

// isWriteActive reports whether an in-flight claim exists for digest, taking
// both the in-process registry and cross-process flocks into account.
func isWriteActive(digest string) bool {
	if digest == "" {
		return false
	}
	return IsBlobInUse(digest)
}
